/**
 * キャリアのシーズンのまとめ（2026-11-14）: 新しいシーズンのはじめ（第 3 週まで）に 1 回。表彰式と会話が済んでから。
 * 前のシーズンの成績・総合値の伸び・今季の目標の結果・表彰・通算の節目・できごと。
 */
import { createPortal } from 'react-dom'
import { useGame, useGameState } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'

export function CareerSeasonReview() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const c = state.career!
  const s = state.season - 1
  const log = c.log.find((l) => l.season === s)
  const p = state.players[c.playerId]
  const h = p.history.find((x) => x.season === s)
  // 表彰式が残っていれば、そのあと
  const ceremonyPending = !!h && c.ceremonySeen !== s && state.awards.some((a) => a.season === s && a.league === h.league)
  const show = !!log && state.week <= 3 && c.reviewSeen !== s && c.talks.length === 0 && !ceremonyPending && c.retiredAt === undefined
  if (!show || !root || !log) return null
  const prev = c.log.filter((l) => l.season < s).pop()
  const dOvr = prev ? log.ovr - prev.ovr : 0
  const goals = c.goals?.season === s ? c.goals : c.goalsLast?.season === s ? c.goalsLast : undefined
  const marks = (c.milestones ?? []).filter((m) => m.season === s)
  const awards = state.awards.filter((a) => a.season === s && a.playerId === p.id)
  const close = () => mutate((st) => void (st.career!.reviewSeen = s))
  const yearLabel = `${state.startYear + s}-${String((state.startYear + s + 1) % 100).padStart(2, '0')}`
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[57] flex items-center justify-center bg-black/60 p-4">
      <div className="panel panel-solid panel-hero flex max-h-full w-[34rem] max-w-full flex-col p-4">
        <div className="text-[0.75rem] font-bold text-ink-dim">{yearLabel} シーズンのまとめ</div>
        <div className="mt-0.5 text-[1.05rem] font-black">
          {log.teamName}
          <span className="ml-1 text-[0.75rem] font-normal text-ink-dim">（{log.league}）・{log.age} 歳</span>
        </div>
        <div className="scroll-y mt-2 min-h-0 space-y-2 text-[0.82rem]">
          <div className="num grid grid-cols-4 gap-1.5 text-center">
            {[
              ['試合', String(log.gp)],
              ['得点', log.ppg.toFixed(1)],
              ['リバウンド', log.rpg.toFixed(1)],
              ['アシスト', log.apg.toFixed(1)],
            ].map(([k, v]) => (
              <div key={k} className="stat-chip px-1 py-1">
                <div className="text-[0.66rem] text-ink-dim">{k}</div>
                <div className="text-[1.05rem] font-black">{v}</div>
              </div>
            ))}
          </div>
          <div className="num">
            総合値 {prev ? `${prev.ovr} → ` : ''}
            <b className="text-gold">{log.ovr}</b>
            {prev && <span className={`ml-1 font-black ${dOvr > 0 ? 'text-good' : dOvr < 0 ? 'text-bad' : 'text-ink-dim'}`}>（{dOvr > 0 ? `+${dOvr}` : dOvr}）</span>}
          </div>
          {goals && goals.judged && (
            <div>
              <div className="text-[0.72rem] font-black text-ink-dim">
                シーズンの目標 {goals.list.filter((g) => g.done).length}/{goals.list.length} 達成
              </div>
              {goals.list.map((g) => (
                <div key={g.kind} className="flex items-center gap-1">
                  <span className={g.done ? 'text-good' : 'text-bad'}>{g.done ? '✓' : '×'}</span>
                  <span>{g.label}</span>
                </div>
              ))}
            </div>
          )}
          {(awards.length > 0 || marks.length > 0) && (
            <div className="flex flex-wrap gap-1.5">
              {awards.map((a) => (
                <span key={a.award} className="rounded-full px-2.5 py-0.5 text-[0.78rem] font-black text-[#2a1a00]" style={{ background: 'linear-gradient(90deg,#f5c542,#ffb347)' }}>
                  {a.award}
                </span>
              ))}
              {marks.map((m) => (
                <span key={m.text} className="rounded-full bg-gold/20 px-2.5 py-0.5 text-[0.78rem] font-bold">
                  {m.text}
                </span>
              ))}
            </div>
          )}
          {log.notes.length > 0 && <div className="text-[0.75rem] text-ink-dim">できごと: {log.notes.join('・')}</div>}
        </div>
        <button className="btn btn-gold mt-3 w-full" onClick={close} data-hotkey="primary">
          新しいシーズンへ
        </button>
      </div>
    </div>,
    root,
  )
}
