/** 1か月オートの前後（AutoRecap.tsx の部品が使う）: 進める前の状態を覚え、進めたあとにまとめを出す */
import { useState } from 'react'
import { rankIn, type GameState } from '../../engine'
import type { WeekReport } from '../../engine/core/advanceWeek'
import { useGame } from '../../stores/gameStore'
import { useSettings } from '../../stores/settingsStore'
import { NBA_DRAFT_WEEK } from '../../engine/core/calendar'
import { hasChoiceScene } from '../../engine/club/story'
import { talkOf } from '../../engine/career/talks'

export interface AutoStart {
  season: number
  week: number
  teamId: number
  rank: number
  money?: number
  fans?: number
}

export function myTeamId(state: GameState): number {
  return state.club ? state.club.teamId : state.career ? state.players[state.career.playerId].teamId : -1
}

export function rankOf(state: GameState, teamId: number): number {
  if (teamId < 0) return 0
  const t = state.teams[teamId]
  const lg = state.leagues[t.league]
  return rankIn(lg, teamId, t.league === 'NBA' ? lg.teamIds.filter((id) => state.teams[id].conf === t.conf) : undefined)
}

export function autoStart(state: GameState): AutoStart {
  const teamId = myTeamId(state)
  return { season: state.season, week: state.week, teamId, rank: rankOf(state, teamId), money: state.club?.money, fans: state.club?.fans }
}

/** 進める前のようす（止まった理由を、増えたもので見分ける） */
interface Before {
  sponsors: number
  offers: Set<number>
  hurt: Set<number>
}
const mineOf = (state: GameState) => (state.club ? state.teams[state.club.teamId].roster : state.career ? [state.career.playerId] : [])
function beforeOf(state: GameState): Before {
  return { sponsors: state.club?.sponsorOffers.length ?? 0, offers: new Set(state.career?.offers.map((o) => o.id)), hurt: new Set(mineOf(state).filter((id) => state.players[id].injury)) }
}

/** 4 週より前で止まった理由（gameStore の advance の止まる条件と同じ順に見る） */
export function stopReason(state: GameState, reports: WeekReport[], before?: Before): string | null {
  if (reports.length >= 4 || reports.length === 0) return null
  if (reports[reports.length - 1].seasonEnded) return 'シーズンが終わったので止まりました'
  if (state.club) {
    if (state.club.gameOver) return null
    if (hasChoiceScene(state)) return '返事の要る話が来たので止まりました'
    if (state.club.bids.some((b) => state.club!.listed?.includes(b.playerId))) return '売りに出した選手に申し入れが来たので止まりました'
    if (state.week === NBA_DRAFT_WEEK && state.teams[state.club.teamId].league === 'NBA' && !state.club.draftBoard?.length) return '指名リストが空のままドラフトの週になったので止まりました'
  }
  const stop = useSettings.getState().autoStop
  if (stop.injury && mineOf(state).some((id) => !before?.hurt.has(id) && (state.players[id].injury?.weeks ?? 0) >= 4)) return state.club ? '長いケガをした選手が出たので止まりました' : '長いケガをしたので止まりました'
  if (state.club && stop.offer && state.club.sponsorOffers.length > (before?.sponsors ?? 0)) return 'スポンサーの申し出が来たので止まりました'
  if (state.career) {
    if (state.career.offers.some((o) => !before?.offers.has(o.id))) return '契約の話が来たので止まりました'
    if (state.career.talks.some((t) => talkOf(t.id, state)?.choices)) return '返事の要る話が来たので止まりました'
  }
  return null
}

/** 1か月オート（4 週）を進めて、2 週以上進んだか、途中で止まったら（理由つきで）まとめを出す */
export function useAutoMonth() {
  const advance = useGame((s) => s.advance)
  const [recap, setRecap] = useState<{ start: AutoStart; reports: WeekReport[]; reason: string | null } | null>(null)
  const run = async (state: GameState) => {
    const start = autoStart(state)
    const before = beforeOf(state)
    const reports = await advance(4)
    const reason = stopReason(state, reports, before)
    if (reports.length >= 2 || reason) setRecap({ start, reports, reason })
  }
  return { run, recap, close: () => setRecap(null) }
}
