/**
 * 白い地で読める色にする（2026-11-14）。ポジション・ランク・経験点の色は夜のテーマのころの明るい色なので、
 * 文字や白い文字の札の地に使うときは、黒を混ぜて白とのコントラストが min 以上になるまで暗くする（色合いはそのまま）。
 */
const memo = new Map<string, string>()

function rgbOf(hex: string): [number, number, number] | null {
  const m = hex.trim().match(/^#([0-9a-f]{3}|[0-9a-f]{6})$/i)
  if (!m) return null
  const h = m[1].length === 3 ? [...m[1]].map((c) => c + c).join('') : m[1]
  return [0, 2, 4].map((i) => parseInt(h.slice(i, i + 2), 16)) as [number, number, number]
}

function luminance([r, g, b]: number[]): number {
  const f = (v: number) => ((v /= 255) <= 0.03928 ? v / 12.92 : ((v + 0.055) / 1.055) ** 2.4)
  return 0.2126 * f(r) + 0.7152 * f(g) + 0.0722 * f(b)
}

/** 白とのコントラスト */
export function contrastOnWhite(hex: string): number {
  const rgb = rgbOf(hex)
  return rgb ? 1.05 / (luminance(rgb) + 0.05) : 21
}

/** 白い地の文字（min 4.5）や、白い文字の札の地（min 3.2）に使える濃さまで暗くした色 */
export function readableOn(hex: string, min = 4.5): string {
  const key = `${hex}:${min}`
  const hit = memo.get(key)
  if (hit) return hit
  const rgb = rgbOf(hex)
  let out = hex
  if (rgb) {
    for (let k = 1; k >= 0.2; k -= 0.04) {
      const c = rgb.map((v) => Math.round(v * k))
      if (1.05 / (luminance(c) + 0.05) >= min) {
        out = `#${c.map((v) => v.toString(16).padStart(2, '0')).join('')}`
        break
      }
    }
  }
  memo.set(key, out)
  return out
}
