/**
 * 1か月オートのまとめ（2026-11-15）: 進めた週のあいだの自分のチームの勝ち負け・順位の上下・大きなニュース。
 * 進める前に `autoStart` で今の状態を覚え、進めたあとに `AutoRecap` を出す。
 */
import { createPortal } from 'react-dom'
import { dateLabel } from '../../engine'
import type { WeekReport } from '../../engine/core/advanceWeek'
import { useGameState } from '../../stores/gameStore'
import { formatMoneyShort } from '../format'
import { useOverlayRoot } from '../stage/overlayRoot'
import { rankOf, type AutoStart } from './autoMonth'

export function AutoRecap({ start, reports, reason, onClose }: { start: AutoStart; reports: WeekReport[]; reason?: string | null; onClose: () => void }) {
  const state = useGameState()
  const root = useOverlayRoot()
  // 会話・場面が残っているあいだは出さない（済んでから）
  const waiting = (state.career?.talks.length ?? 0) > 0 || (state.club?.scenes?.length ?? 0) > 0
  if (!root || waiting) return null
  const teamId = start.teamId
  const weeks = new Set(reports.map((r) => `${r.season}:${r.week}`))
  // シーズンが変わっていれば日程は入れ替わっているので、今のシーズンの分だけ数える
  const games = state.fixtures.filter((f) => f.result && (f.home === teamId || f.away === teamId) && weeks.has(`${state.season}:${f.week}`))
  const w = games.filter((f) => (f.home === teamId ? f.result!.hs > f.result!.as : f.result!.as > f.result!.hs)).length
  const l = games.length - w
  const rank1 = state.season === start.season ? rankOf(state, teamId) : 0
  const big = reports.flatMap((r) => r.news.filter((n) => n.big)).slice(-5)
  const team = teamId >= 0 ? state.teams[teamId] : undefined
  const first = reports[0]
  const last = reports[reports.length - 1]
  return createPortal(
    <div className="anim-fade absolute inset-0 z-40 flex items-center justify-center bg-black/55 p-4" onClick={onClose}>
      <div className="panel panel-solid max-h-full w-[30rem] max-w-full overflow-y-auto p-4" onClick={(e) => e.stopPropagation()}>
        <div className="text-[0.75rem] font-bold text-ink-dim">
          {dateLabel(state.startYear, first.season, first.week)} 〜 {dateLabel(state.startYear, last.season, last.week)}（{reports.length} 週）
        </div>
        <div className="text-[1rem] font-black">{reports.length >= 4 ? '1か月のまとめ' : `${reports.length} 週のまとめ`}</div>
        {reason && <div className="mt-0.5 rounded-md bg-gold/15 px-2 py-0.5 text-[0.78rem] font-bold">{reason}</div>}
        {team && games.length > 0 && (
          <div className="mt-2 flex flex-wrap items-center gap-2 text-[0.85rem]">
            <span className="num text-[1.2rem] font-black">
              {w} 勝 {l} 敗
            </span>
            <span className="flex gap-[0.18rem]">
              {games.map((f) => {
                const win = f.home === teamId ? f.result!.hs > f.result!.as : f.result!.as > f.result!.hs
                return <span key={f.id} className={`h-[0.62rem] w-[0.62rem] rounded-full ${win ? 'border-2 border-good' : 'bg-bad'}`} />
              })}
            </span>
            {start.rank > 0 && rank1 > 0 && (
              <span className={`rounded-full px-2 py-0.5 text-[0.78rem] font-black ${rank1 < start.rank ? 'bg-good/15 text-good' : rank1 > start.rank ? 'bg-bad/10 text-bad' : 'bg-black/[0.05] text-ink-dim'}`}>
                順位 {start.rank} → {rank1} 位
              </span>
            )}
          </div>
        )}
        {team && games.length === 0 && <div className="mt-2 text-[0.82rem] text-ink-dim">このあいだは試合がありませんでした。</div>}
        {state.club && start.money !== undefined && (
          <div className="num mt-1.5 flex gap-3 text-[0.8rem]">
            <span>
              資金 <b className={state.club.money - start.money >= 0 ? 'text-good' : 'text-bad'}>{state.club.money - start.money >= 0 ? '+' : ''}{formatMoneyShort(Math.round(state.club.money - start.money))}円</b>
            </span>
            <span>
              ファン <b>{state.club.fans - (start.fans ?? 0) >= 0 ? '+' : ''}{(state.club.fans - (start.fans ?? 0)).toLocaleString()}</b>
            </span>
          </div>
        )}
        {big.length > 0 && (
          <div className="mt-2 space-y-0.5 text-[0.76rem]">
            {big.map((n, i) => (
              <div key={i} className="font-bold text-gold">
                ・{n.text}
              </div>
            ))}
          </div>
        )}
        <button className="btn btn-gold mt-3 w-full" onClick={onClose} data-hotkey="primary">
          OK
        </button>
      </div>
    </div>,
    root,
  )
}
