/**
 * お金がかかる・取り消せない操作の前の確認（2026-11-15）。
 *   const confirm = useConfirm()
 *   onClick={() => confirm.ask({ title, text, ok }, () => mutate(...))}
 *   ...画面のどこかに {confirm.dialog}
 */
import { useState, type ReactNode } from 'react'
import { ConfirmDialog } from '../components/ConfirmDialog'

interface Ask {
  title: string
  text?: string
  ok: string
}

export function useConfirm(): { ask: (a: Ask, run: () => void) => void; dialog: ReactNode } {
  const [pending, setPending] = useState<(Ask & { run: () => void }) | null>(null)
  const dialog = (
    <ConfirmDialog
      open={!!pending}
      title={pending?.title ?? ''}
      text={pending?.text}
      ok={pending?.ok ?? 'OK'}
      onOk={() => {
        const p = pending
        setPending(null)
        p?.run()
      }}
      onCancel={() => setPending(null)}
    />
  )
  return { ask: (a, run) => setPending({ ...a, run }), dialog }
}
