/** 試合のない週: 「試合はありません」と、次の試合がいつか（相手と、あと何週） */
import { dateLabel, nextFixture } from '../../engine'
import { useGameState } from '../../stores/gameStore'

export function NoGame({ teamId, text }: { teamId: number; text: string }) {
  const state = useGameState()
  const next = nextFixture(state, teamId)
  return (
    <div className="text-[0.8rem] text-ink-dim">
      試合はありません。{text}
      {next && (
        <div className="mt-0.5">
          次の試合: <b className="text-ink">{state.teams[next.opp].name}</b>（{dateLabel(state.startYear, state.season, next.week)}・あと <b className="num text-gold">{next.in}</b> 週）
        </div>
      )}
    </div>
  )
}
