export function menuGroups(state: GameState): MenuGroup[] {
  return state.mode === 'career' ? CAREER_MENU : CLUB_MENU
}

/** ナビとメニューの知らせの数（返事を待っているもの）。キーは画面 か 画面:タブ */
export function badgesOf(state: GameState): Partial<Record<string, number>> {
  const c = state.club
  if (!c) {
    // キャリア: 返事を待っている契約の話
    const n = state.career?.path ? state.career.offers.length : 0
    // じっくり育成: 経験点で上げられる能力の数
    const g = state.career ? raisableCount(state) : 0
    return { career: n, 'career:offers': n, growth: g, 'growth:attr': g }
  }
  const offers = new Set(c.sponsorOffers.map((o) => o.slot)).size
  return { club: offers, 'club:sponsor': offers, transfer: c.bids.length, 'transfer:bids': c.bids.length }
}

/** じっくり育成で、いまの経験点で 1 上げられる能力の数（かんたん育成は自動で振るので 0） */
function raisableCount(state: GameState): number {
  const c = state.career!
  if (c.growthMode !== 'careful') return 0
  const p = state.players[c.playerId]
  return ATTR_KEYS.filter((k) => {
    const v = Math.round(p.attr[k])
    return v < 99 && c.exp[EXP_OF[k]] >= attrCost(v)
  }).length
}
