/**
 * PC のキーボード（2026-11-14）: Space・Enter で、いちばん上に見えている「主な操作」（data-hotkey="primary"）を押す。
 *   会話を進める・まとめの OK・次へ進む・試合の結果の次へ など。観戦中の Space は一時停止（主な操作が停止のボタン）。
 * Esc は、いちばん上の閉じるボタン（data-hotkey="close"）を押す。なければ前の画面に戻る（戻り先がなければホーム）。
 * 数字のキーは data-hotkey="key-N"（観戦の速さ 1〜4）。
 * 文字を打っている欄では何もしない。ボタンにフォーカスがあるときはブラウザに任せる（その上に重ね物が出ていれば重ね物の主な操作）。
 */
import { useUi } from '../../stores/uiStore'

function visible(el: Element): boolean {
  if (!(el instanceof HTMLElement)) return false
  if ((el as HTMLButtonElement).disabled) return false
  const r = el.getBoundingClientRect()
  if (r.width < 1 || r.height < 1) return false
  const cs = getComputedStyle(el)
  return cs.visibility !== 'hidden' && cs.pointerEvents !== 'none'
}

/** いちばん上（DOM の後ろ。重ね物は画面の後ろに描かれる）の見えている要素 */
function topmost(sel: string): HTMLElement | null {
  const all = [...document.querySelectorAll(sel)].filter(visible)
  return (all[all.length - 1] as HTMLElement | undefined) ?? null
}

let installed = false

export function installHotkeys() {
  if (installed || typeof window === 'undefined') return
  installed = true
  window.addEventListener('keydown', (e) => {
    if (e.isComposing || e.ctrlKey || e.metaKey || e.altKey) return
    const t = e.target as HTMLElement | null
    if (t && (t.tagName === 'INPUT' || t.tagName === 'TEXTAREA' || t.isContentEditable)) return
    const onButton = !!t && (t.tagName === 'BUTTON' || t.getAttribute('role') === 'button')
    if (e.key === ' ' || e.key === 'Enter') {
      const el = topmost('[data-hotkey="primary"]')
      // ボタンにフォーカスがあれば、ふつうはブラウザがそのボタンを押す。ただし、その上に重ね物の主な操作が出ているときは
      // （前に押した「次へ進む」にフォーカスが残ったまま、まとめが開いているなど）重ね物のほうを押す
      if (onButton && (!el || el === t || el.contains(t!) || !(t!.compareDocumentPosition(el) & Node.DOCUMENT_POSITION_FOLLOWING))) return
      if (!el) return
      e.preventDefault()
      el.click()
    } else if (/^[1-9]$/.test(e.key)) {
      // 数字: その番号の操作（観戦の速さ ×1・×2・×4・×8 など。data-hotkey="key-N"）
      const el = topmost(`[data-hotkey="key-${e.key}"]`)
      if (!el) return
      e.preventDefault()
      el.click()
    } else if (e.key === 'Escape') {
      const el = topmost('[data-hotkey="close"]')
      e.preventDefault()
      if (el) el.click()
      else {
        // 前の画面へ（戻り先がなければホーム。ホームとタイトルでは何もしない）
        const ui = useUi.getState()
        const cur = ui.stack[ui.stack.length - 1]?.id
        if (cur && cur !== 'home' && cur !== 'title') ui.pop()
      }
    }
  })
}
