/**
 * 振動（2026-11-15）: 対応している端末（Android の Chrome など）で、勝利・見せ場の成功・記録などに短い振動。
 * iPhone のブラウザは振動に対応していないので何も起きない。設定の「振動」でオフにできる。
 */
import { useSettings } from '../../stores/settingsStore'

const PATTERNS = {
  /** 軽い手ごたえ（見せ場の成功・3P・ダンク） */
  tap: 18,
  /** 勝利・記録 */
  win: [30, 60, 40],
  /** 大きな出来事（優勝・節目） */
  big: [40, 70, 40, 70, 90],
} as const

export function buzz(kind: keyof typeof PATTERNS) {
  if (!useSettings.getState().haptics) return
  if (typeof navigator === 'undefined' || typeof navigator.vibrate !== 'function') return
  // まだ画面に触れていないとブラウザが断って警告を出すので、触れたあとだけ
  const ua = (navigator as Navigator & { userActivation?: { hasBeenActive: boolean } }).userActivation
  if (ua && !ua.hasBeenActive) return
  try {
    navigator.vibrate(PATTERNS[kind] as number | number[])
  } catch {
    // 断られても気にしない
  }
}
