/**
 * 補強・編成の「レンタル」タブ（club/loan.ts）: 貸し出している・借りている選手、貸し出す候補（24 歳まで）、借りる候補（上の部の控え）。
 */
import { ovr, ageOf } from '../../engine'
import { clubTeam } from '../../engine/club/manage'
import { LOAN_AGE_MAX, LOAN_IN_MAX, LOAN_OUT_MAX, loanDestination, loanFee, loanIn, loanInCandidates, loanInProblem, loanOut, loanOutProblem } from '../../engine/club/loan'
import { rankIfJoined } from '../../engine/club/transfer'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { OvrBadge, PosBadge } from '../components/common'
import { Term } from '../components/Term'
import { useConfirm } from '../hooks/useConfirm'
import { formatMoneyShort } from '../format'

const yen = (man: number) => `${formatMoneyShort(Math.round(man))}円`

export function LoanTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const push = useUi((s) => s.push)
  const confirm = useConfirm()
  const c = state.club!
  const team = clubTeam(state)
  const outs = (c.loanOut ?? []).map((id) => state.players[id]).filter(Boolean)
  const ins = (c.loanIn ?? []).map((id) => state.players[id]).filter(Boolean)
  const mine = team.roster
    .map((id) => state.players[id])
    .filter((p) => !p.loan && ageOf(state, p) <= LOAN_AGE_MAX)
    .sort((a, b) => ovr(b) - ovr(a))
  const cands = loanInCandidates(state).slice(0, 30)
  const Name = ({ id, name }: { id: number; name: string }) => (
    <button className="min-w-0 flex-1 truncate text-left text-[0.84rem] font-bold" onClick={() => push({ id: 'player', params: { playerId: id } })}>
      {name}
    </button>
  )
  return (
    <div className="space-y-3">
      {confirm.dialog}
      <p className="text-[0.74rem] leading-snug text-ink-dim">
        <Term id="loan">レンタル移籍</Term>はシーズンの終わりまでの貸し借りです。出番の少ない若手を下の部で試合に出して伸ばす・上の部の控えを借りて戦力にする、のどちらにも使えます。年俸はどちらも半分を払い、借りるときはレンタル料（年俸の 3 割）も払います。シーズンの終わりに元のクラブへ戻ります（経歴にはレンタル先で残る）。移籍の期間だけ。
      </p>
      {(outs.length > 0 || ins.length > 0) && (
        <div className="panel-flat p-2">
          <div className="panel-head mb-1">いまのレンタル</div>
          {outs.map((p) => (
            <div key={p.id} className="flex items-center gap-2 py-0.5 text-[0.8rem]">
              <span className="w-[4.2rem] shrink-0 rounded bg-[#2a7fdc]/15 px-1 text-center text-[0.66rem] font-black text-[#1f5fae]">貸し出し中</span>
              <PosBadge pos={p.pos} />
              <Name id={p.id} name={p.name} />
              <span className="text-ink-dim">→ {state.teams[p.teamId]?.short}</span>
              <span className="num text-ink-dim">
                {p.stats.gp} 試合・平均 {p.stats.gp ? (p.stats.pts / p.stats.gp).toFixed(1) : '0.0'} 点
              </span>
              <OvrBadge value={ovr(p)} size="sm" />
            </div>
          ))}
          {ins.map((p) => (
            <div key={p.id} className="flex items-center gap-2 py-0.5 text-[0.8rem]">
              <span className="w-[4.2rem] shrink-0 rounded bg-orange/20 px-1 text-center text-[0.66rem] font-black text-orange">借りている</span>
              <PosBadge pos={p.pos} />
              <Name id={p.id} name={p.name} />
              <span className="text-ink-dim">← {p.loan ? state.teams[p.loan.owner]?.short : ''}</span>
              <span className="num text-ink-dim">年俸の半分 {yen(p.contract.salary / 2)}</span>
              <OvrBadge value={ovr(p)} size="sm" />
            </div>
          ))}
          <div className="mt-0.5 text-[0.68rem] text-ink-mute">シーズンの終わりに元のクラブへ戻ります。</div>
        </div>
      )}
      <div>
        <div className="panel-head mb-1">
          貸し出す（{LOAN_AGE_MAX} 歳まで・{outs.length}/{LOAN_OUT_MAX} 人）
        </div>
        {mine.length === 0 && <div className="px-1 text-[0.8rem] text-ink-dim">{LOAN_AGE_MAX} 歳までの選手がいません。</div>}
        {mine.map((p) => {
          const why = loanOutProblem(state, p)
          const dest = why ? undefined : loanDestination(state, p)
          return (
            <div key={p.id} className="flex items-center gap-2 rounded-lg px-1.5 py-1 hover:bg-black/[0.03]">
              <PosBadge pos={p.pos} />
              <Name id={p.id} name={p.name} />
              <span className="num w-9 text-right text-[0.72rem] text-ink-dim">{ageOf(state, p)}歳</span>
              <OvrBadge value={ovr(p)} size="sm" />
              <span className="w-[13rem] truncate text-right text-[0.72rem]">
                {why ? <span className="text-ink-mute">{why}</span> : dest ? <>行き先 <b>{dest.team.short}</b>（{state.leagues[dest.team.league].name}・{dest.rank} 番手）</> : <span className="text-ink-mute">貸し出せるクラブがない</span>}
              </span>
              <button
                className="btn btn-blue btn-sm !h-7 w-[5.6rem] shrink-0 !px-1"
                disabled={!!why || !dest}
                onClick={() =>
                  dest &&
                  confirm.ask({ title: `${p.name}を${dest.team.name}へ貸し出しますか？`, text: `シーズンの終わりまで（${dest.rank} 番手の見込み）。年俸の半分（年 ${yen(p.contract.salary / 2)}）は払い続けます。シーズンの終わりに戻ってきます。`, ok: '貸し出す' }, () => mutate((st) => void loanOut(st, p.id)))
                }
              >
                <span className="text-[0.76rem]">貸し出す</span>
              </button>
            </div>
          )
        })}
      </div>
      <div>
        <div className="panel-head mb-1">
          借りる（同じか上の部の控えの若手・{ins.length}/{LOAN_IN_MAX} 人）
        </div>
        {cands.length === 0 && <div className="px-1 text-[0.8rem] text-ink-dim">いまは借りられる選手がいません（入れば 9 番手より上に入る、{LOAN_AGE_MAX} 歳までの控え）。</div>}
        {cands.map((p) => {
          const why = loanInProblem(state, p)
          const rank = rankIfJoined(state, p)
          return (
            <div key={p.id} className="flex items-center gap-2 rounded-lg px-1.5 py-1 hover:bg-black/[0.03]">
              <PosBadge pos={p.pos} />
              <Name id={p.id} name={p.name} />
              <span className="num w-9 text-right text-[0.72rem] text-ink-dim">{ageOf(state, p)}歳</span>
              <OvrBadge value={ovr(p)} size="sm" />
              <span className={`num w-[3.4rem] shrink-0 text-center text-[0.7rem] font-black ${rank <= 5 ? 'text-gold' : 'text-good'}`}>{rank} 番手</span>
              <span className="w-[11.6rem] truncate text-right text-[0.72rem]">
                {state.teams[p.teamId].short}・年 {yen(p.contract.salary / 2)}・料 {yen(loanFee(p))}
              </span>
              <button
                className="btn btn-gold btn-sm !h-7 w-[5.6rem] shrink-0 !px-1"
                disabled={!!why}
                title={why ?? undefined}
                onClick={() => confirm.ask({ title: `${p.name}を借りますか？`, text: `${state.teams[p.teamId].name}からシーズンの終わりまで。レンタル料 ${yen(loanFee(p))} をその場で払い、年俸の半分（年 ${yen(p.contract.salary / 2)}）を払います。売ったり契約を解除したりはできません。`, ok: '借りる' }, () => mutate((st) => void loanIn(st, p.id)))}
              >
                <span className="text-[0.76rem]">借りる</span>
              </button>
            </div>
          )
        })}
      </div>
    </div>
  )
}
