/**
 * リーグの個人成績のランキング（2026-11-15）: 得点・リバウンド・アシスト・スティール・ブロックの 1 試合あたりの上位 10 人。
 * 出場が少ない選手は外す（チームのいちばん多い試合数の 3 分の 1 以上）。主人公と自分のクラブの選手は色を付ける。
 */
import { useState, type ReactNode } from 'react'
import type { GameState, Player } from '../../engine'
import { useUi } from '../../stores/uiStore'
import { PosBadge, TeamDot } from '../components/common'

const CATS = [
  ['pts', '得点'],
  ['reb', 'リバウンド'],
  ['ast', 'アシスト'],
  ['stl', 'スティール'],
  ['blk', 'ブロック'],
] as const
type Cat = (typeof CATS)[number][0]

const value = (p: Player, c: Cat) => (c === 'reb' ? p.stats.oreb + p.stats.dreb : p.stats[c]) / Math.max(1, p.stats.gp)

export function Leaders({ state, teamIds, head }: { state: GameState; teamIds: number[]; head?: ReactNode }) {
  const push = useUi((s) => s.push)
  const [cat, setCat] = useState<Cat>('pts')
  const players = teamIds.flatMap((id) => state.teams[id].roster.map((pid) => state.players[pid]))
  const most = Math.max(0, ...teamIds.map((id) => state.leagues[state.teams[id].league].standings[id]).map((s) => (s ? s.w + s.l : 0)))
  const need = Math.max(1, Math.floor(most / 3))
  const list = players
    .filter((p) => p.stats.gp >= need)
    .sort((a, b) => value(b, cat) - value(a, cat))
    .slice(0, 10)
  const mine = (p: Player) => p.isPlayer || (!!state.club && p.teamId === state.club.teamId)
  // 主人公が 10 位より下なら、何位かを下に
  const me = state.career ? state.players[state.career.playerId] : undefined
  const myRank = me && teamIds.includes(me.teamId) && me.stats.gp >= need && !list.includes(me) ? players.filter((p) => p.stats.gp >= need && value(p, cat) > value(me, cat)).length + 1 : 0
  if (most === 0)
    return (
      <div className="p-2">
        {head}
        <div className="p-2 text-[0.85rem] text-ink-dim">まだ試合がありません。</div>
      </div>
    )
  return (
    <div className="p-2">
      <div className="mb-1.5 flex flex-wrap items-center gap-2">
        {head}
        <div className="seg">
          {CATS.map(([id, label]) => (
            <button key={id} aria-selected={cat === id} onClick={() => setCat(id)} className="!px-2.5">
              {label}
            </button>
          ))}
        </div>
        <span className="text-[0.7rem] text-ink-dim">1 試合あたり・{need} 試合以上</span>
      </div>
      <table className="num w-full text-[0.84rem]">
        <tbody>
          {list.map((p, i) => {
            const t = state.teams[p.teamId]
            return (
              <tr key={p.id} className={`cv-row border-t border-line/30 hover:bg-black/5 ${mine(p) ? 'bg-gold/15' : ''}`} onClick={() => push({ id: 'player', params: { playerId: p.id } })}>
                <td className={`w-8 py-1 text-center font-black ${i < 3 ? 'text-gold' : 'text-ink-dim'}`}>{i + 1}</td>
                <td>
                  <span className="flex items-center gap-2">
                    <PosBadge pos={p.pos} />
                    <span className={`truncate ${mine(p) ? 'font-black' : 'font-bold'}`}>{p.name}</span>
                  </span>
                </td>
                <td className="text-[0.74rem] text-ink-dim">
                  <span className="flex items-center gap-1.5">
                    <TeamDot colors={t.colors} abbr={t.abbr} className="h-5 w-5 text-[0.45rem]" />
                    {t.short}
                  </span>
                </td>
                <td className="w-12 text-center text-[0.74rem] text-ink-dim">{p.stats.gp} 試合</td>
                <td className="w-16 pr-2 text-right text-[1rem] font-black">{value(p, cat).toFixed(1)}</td>
              </tr>
            )
          })}
        </tbody>
      </table>
      {myRank > 0 && me && (
        <div className="mt-1 rounded-lg bg-gold/10 px-2 py-1 text-[0.8rem]">
          あなた（{me.short}）は <b className="num">{myRank}</b> 位・<b className="num">{value(me, cat).toFixed(1)}</b>
        </div>
      )}
    </div>
  )
}
