/**
 * 選手の画面の「比べる」タブ（2026-11-14）: 自分のチーム（クラブ経営は自分のクラブ、キャリアは主人公のチーム）の選手と並べて比べる。
 * 同じポジションの選手を先に。レーダーを重ねて（この選手はオレンジ・相手は青）、能力ごとの差・総合値・年齢・体格・年俸・見込み。
 */
import { ATTR_CATS, ATTR_DEFS, ATTR_KEYS, POS_WEIGHTS, RADAR_AXES, ageOf, ovr, radarValues, type GameState, type Player } from '../../engine'
import { OvrBadge, PosBadge } from '../components/common'
import { RadarChart } from '../components/RadarChart'
import { useScreenState } from '../hooks/useScreenState'
import { salaryLabel } from '../money'
import { outlookOf } from '../components/outlookData'

/** 比べる相手の候補: 自分のチームの選手（この選手は除く）。同じポジション → 2 つ目のポジションが同じ → 総合値の順 */
function candidates(state: GameState, p: Player): Player[] {
  const myTeam = state.club ? state.club.teamId : state.career ? state.players[state.career.playerId].teamId : -1
  const teamId = myTeam >= 0 && myTeam !== p.teamId ? myTeam : p.teamId
  if (teamId < 0) return []
  const rank = (q: Player) => (q.pos === p.pos ? 0 : q.pos2 === p.pos || q.pos === p.pos2 ? 1 : 2)
  return state.teams[teamId].roster
    .map((id) => state.players[id])
    .filter((q) => q.id !== p.id)
    .sort((a, b) => rank(a) - rank(b) || ovr(b) - ovr(a))
}

export function CompareTab({ state, p }: { state: GameState; p: Player }) {
  const list = candidates(state, p)
  const [otherId, setOtherId] = useScreenState<number>('compare', list[0]?.id ?? -1)
  const q = state.players[otherId] && otherId !== p.id ? state.players[otherId] : list[0]
  if (!q) return <div className="p-2 text-[0.8rem] text-ink-dim">比べられる選手がいません。</div>
  const weight = POS_WEIGHTS[p.pos]
  const op = outlookOf(state, p)
  const oq = outlookOf(state, q)
  const rows: [string, string, string, number][] = [
    ['総合', String(ovr(p)), String(ovr(q)), ovr(p) - ovr(q)],
    ['年齢', `${ageOf(state, p)} 歳`, `${ageOf(state, q)} 歳`, 0],
    ['身長', `${p.heightCm} cm`, `${q.heightCm} cm`, p.heightCm - q.heightCm],
    ['見込み（いちばん高い値）', op ? String(op.peak) : '？', oq ? String(oq.peak) : '？', op && oq ? op.peak - oq.peak : 0],
    ['年俸', p.teamId >= 0 ? salaryLabel(p.contract.salary, state.teams[p.teamId].league) : '-', q.teamId >= 0 ? salaryLabel(q.contract.salary, state.teams[q.teamId].league) : '-', 0],
  ]
  return (
    <div className="flex flex-col gap-2">
      {/* 相手を選ぶ */}
      <div className="flex flex-wrap gap-1">
        {list.slice(0, 15).map((x) => (
          <button key={x.id} onClick={() => setOtherId(x.id)} className={`rounded-lg border px-1.5 py-0.5 ${x.id === q.id ? 'border-[#2a7fdc] bg-[#2a7fdc]/12' : 'border-line/50 bg-black/[0.03]'}`}>
            {/* 文字の大きさは中に（button の font: inherit がレイヤーの外のため） */}
            <span className={`flex items-center gap-1 text-[0.72rem] ${x.id === q.id ? 'font-black' : ''}`}>
              <span className="font-black text-ink-dim">{x.pos}</span>
              {x.short}
              <span className="num text-ink-dim">{ovr(x)}</span>
            </span>
          </button>
        ))}
      </div>
      <div className="flex gap-3">
        <div className="flex shrink-0 flex-col items-center">
          <RadarChart labels={RADAR_AXES.map((a) => a.label)} values={radarValues(p.attr)} compare={radarValues(q.attr)} color="#ff7a1a" compareColor="#2a7fdc" className="h-[13rem] w-[13rem]" />
          <div className="flex items-center gap-3 text-[0.72rem] font-bold">
            <span className="flex items-center gap-1">
              <span className="h-2.5 w-2.5 rounded-full bg-[#ff7a1a]" />
              {p.short}
            </span>
            <span className="flex items-center gap-1">
              <span className="h-2.5 w-2.5 rounded-full bg-[#2a7fdc]" />
              {q.short}
            </span>
          </div>
        </div>
        <div className="min-w-0 flex-1">
          <div className="mb-1 flex items-center gap-2 text-[0.8rem]">
            <PosBadge pos={p.pos} />
            <b className="min-w-0 flex-1 truncate">{p.name}</b>
            <OvrBadge value={ovr(p)} size="sm" />
            <span className="text-ink-mute">vs</span>
            <OvrBadge value={ovr(q)} size="sm" />
            <b className="min-w-0 flex-1 truncate text-right">{q.name}</b>
            <PosBadge pos={q.pos} />
          </div>
          <table className="num w-full text-[0.76rem]">
            <tbody>
              {rows.map(([label, a, b, d]) => (
                <tr key={label} className="border-t border-line/30">
                  <td className="py-0.5 text-ink-dim">{label}</td>
                  <td className={`text-right font-bold ${d > 0 ? 'text-good' : ''}`}>{a}</td>
                  <td className={`text-right font-bold ${d < 0 ? 'text-good' : ''}`}>{b}</td>
                </tr>
              ))}
            </tbody>
          </table>
          <div className="mt-1.5 grid grid-cols-2 gap-x-3">
            {ATTR_CATS.map((c) => (
              <div key={c.id} className="mb-1">
                <div className="text-[0.68rem] font-black text-gold">{c.label}</div>
                {ATTR_KEYS.filter((k) => ATTR_DEFS[k].cat === c.id).map((k) => {
                  const a = Math.round(p.attr[k])
                  const b = Math.round(q.attr[k])
                  const d = a - b
                  return (
                    <div key={k} className="num flex items-center gap-1 text-[0.72rem]">
                      <span className="w-[0.7rem] shrink-0 text-center text-[0.62rem] font-black text-gold">{weight[k] >= 1.2 ? '◎' : weight[k] >= 0.8 ? '○' : ''}</span>
                      <span className="min-w-0 flex-1 truncate">{ATTR_DEFS[k].label}</span>
                      <span className={`w-6 text-right font-bold ${d > 0 ? 'text-[#c2560e]' : ''}`}>{a}</span>
                      <span className={`w-6 text-right font-bold ${d < 0 ? 'text-[#1f5fae]' : ''}`}>{b}</span>
                      <span className={`w-7 text-right text-[0.66rem] font-black ${d > 0 ? 'text-good' : d < 0 ? 'text-bad' : 'text-ink-mute'}`}>{d > 0 ? `+${d}` : d}</span>
                    </div>
                  )
                })}
              </div>
            ))}
          </div>
          <div className="text-[0.66rem] text-ink-mute">差は {p.short} から見た値（+ は {p.short} が上）。◎○ は {p.short} のポジションの総合値に大きく効く能力。</div>
        </div>
      </div>
    </div>
  )
}
