/**
 * 試合のプレビュー（2026-11-14）: 観戦するか決める小窓に。両チームの成績・直近 5 試合・戦力（上位 8 人の平均）・注目の選手（総合値の 1 位）。
 * 主人公がいれば、こちらの注目の選手は主人公。
 */
import { ovr, teamPower, type Fixture, type GameState, type Team } from '../../engine'
import { FormChips, OvrBadge, TeamDot } from '../components/common'
import { rivalPlayer } from '../../engine/career/rival'
import { derbyRecord, derbyRival, isDerby } from '../../engine/club/derby'

function Side({ state, team, focus, right, showLeague }: { state: GameState; team: Team; focus?: number; right?: boolean; showLeague?: boolean }) {
  const st = state.leagues[team.league].standings[team.id]
  const star = focus !== undefined && team.roster.includes(focus) ? state.players[focus] : team.roster.map((id) => state.players[id]).sort((a, b) => ovr(b) - ovr(a))[0]
  return (
    <div className={`flex min-w-0 flex-1 flex-col gap-0.5 ${right ? 'items-end text-right' : ''}`}>
      <div className={`flex min-w-0 items-center gap-1.5 ${right ? 'flex-row-reverse' : ''}`}>
        <TeamDot colors={team.colors} abbr={team.abbr} className="h-6 w-6 text-[0.5rem]" />
        <span className="truncate text-[0.82rem] font-black">{team.short}</span>
      </div>
      <div className="num text-[0.72rem] text-ink-dim">
        {showLeague && <b className="text-ink">{state.leagues[team.league].name}・</b>}
        {st ? `${st.w}勝${st.l}敗` : ''}・戦力 <b className="text-ink">{teamPower(state, team).toFixed(1)}</b>
      </div>
      <FormChips state={state} teamId={team.id} />
      {star && (
        <div className={`flex min-w-0 items-center gap-1 text-[0.72rem] ${right ? 'flex-row-reverse' : ''}`}>
          <span className="shrink-0 text-ink-mute">{star.id === focus ? 'あなた' : '注目'}</span>
          <span className="min-w-0 truncate font-bold">{star.short}</span>
          <OvrBadge value={ovr(star)} size="sm" />
        </div>
      )}
    </div>
  )
}

export function MatchPreview({ state, f, focus }: { state: GameState; f: Fixture; focus?: number }) {
  const home = state.teams[f.home]
  const away = state.teams[f.away]
  // キャリア: 相手にライバル（神崎レオ）がいれば「ライバル対決」（二代目では出ない）
  const leo = focus !== undefined && state.career && !state.career.lineage?.length ? rivalPlayer(state) : undefined
  const myTeam = focus !== undefined ? state.players[focus]?.teamId : -1
  const rivalGame = !!leo && leo.teamId >= 0 && leo.teamId !== myTeam && (leo.teamId === f.home || leo.teamId === f.away)
  const rec = state.career?.rival
  // クラブ: 宿敵との試合は「ダービー」
  const derby = isDerby(state, f) ? derbyRival(state) : undefined
  const drec = derby ? derbyRecord(state, derby.id) : undefined
  return (
    <>
      {derby && (
        <div className="mt-1.5 flex items-center gap-2 rounded-lg bg-bad/10 px-2 py-1 text-[0.8rem]">
          <span className="shrink-0 whitespace-nowrap rounded bg-bad px-1.5 py-0.5 text-[0.68rem] font-black text-white">ダービー</span>
          <span className="min-w-0">
            <b>宿敵 {derby.short}</b>
            <span className="ml-1 text-[0.7rem] text-ink-dim">観客が増える・勝てば人気とファン</span>
          </span>
          {drec && drec.w + drec.l > 0 && (
            <span className="num ml-auto shrink-0 text-ink-dim">
              通算 {drec.w} 勝 {drec.l} 敗
            </span>
          )}
        </div>
      )}
      {rivalGame && (
        <div className="mt-1.5 flex items-center gap-2 rounded-lg bg-bad/10 px-2 py-1 text-[0.8rem]">
          <span className="rounded bg-bad px-1.5 py-0.5 text-[0.68rem] font-black text-white">ライバル対決</span>
          <span className="font-bold">{leo!.name}</span>
          <OvrBadge value={ovr(leo!)} size="sm" />
          {rec && rec.w + rec.l > 0 && (
            <span className="num ml-auto text-ink-dim">
              これまで {rec.w} 勝 {rec.l} 敗
            </span>
          )}
        </div>
      )}
      <div className="mt-1.5 flex items-start gap-2 rounded-lg bg-black/[0.04] px-2 py-1.5">
        <Side state={state} team={home} focus={focus} showLeague={home.league !== away.league} />
        <div className="shrink-0 self-center text-[0.7rem] font-black text-ink-mute">{f.neutral ? '中立地' : 'ホーム ← → アウェイ'}</div>
        <Side state={state} team={away} focus={focus} right showLeague={home.league !== away.league} />
      </div>
    </>
  )
}
