/**
 * キャリアのホームの「今季の目標」（engine/career/goals.ts）: 目標ごとに、いまの値と進み具合のバー。
 * レギュラーシーズンが終わると「達成」「届かず」。
 */
import { goalMet, goalValue } from '../../engine/career/goals'
import { useGameState } from '../../stores/gameStore'
import { Term } from '../components/Term'

export function GoalsPanel() {
  const state = useGameState()
  const c = state.career!
  const goals = c.goals
  if (!goals || goals.season !== state.season) return null
  const done = goals.list.filter((g) => g.done).length
  return (
    <div className="stat-chip px-2 py-1.5 text-[0.72rem]">
      <div className="mb-0.5 flex items-center font-black text-ink-dim">
        <Term id="seasonGoals">今季の目標</Term>
        {goals.judged && <span className={`ml-auto ${done === goals.list.length ? 'text-gold' : ''}`}>{done}/{goals.list.length} 達成</span>}
      </div>
      {goals.list.map((g) => {
        const v = goalValue(state, g, goals)
        const met = goalMet(state, g, goals)
        const ratio = g.kind === 'rank' ? (v > 0 ? Math.min(1, g.target / v) : 0) : g.kind === 'allstar' ? v : Math.min(1, v / g.target)
        const now = g.kind === 'rank' ? (v > 0 ? `いま ${v} 位` : '') : g.kind === 'allstar' ? (v ? '選ばれた' : '2 月に発表') : `${v} / ${g.target}`
        return (
          <div key={g.kind} className="mt-0.5">
            <div className="flex items-center gap-1">
              <span className={`shrink-0 ${g.done === true || (g.done === undefined && met) ? 'text-good' : g.done === false ? 'text-bad' : 'text-ink-mute'}`}>{g.done === true ? '✓' : g.done === false ? '×' : met ? '✓' : '・'}</span>
              <span className="min-w-0 flex-1 truncate font-bold">{g.label}</span>
              <span className="num shrink-0 text-ink-dim">{g.done === true ? '達成' : g.done === false ? '届かず' : now}</span>
            </div>
            {g.done === undefined && g.kind !== 'allstar' && (
              <div className="ml-3 h-[0.28rem] rounded-full bg-black/[0.07]">
                <div className={`h-full rounded-full ${met ? 'bg-good' : 'bg-gold'}`} style={{ width: `${Math.round(ratio * 100)}%` }} />
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}
