/**
 * 試合の観戦（2D・上から）。エンジンを 1 ポゼッションずつ進め、choreo.ts の動きを描く。
 * 再生は VIEW_RATE 倍（×1 で 48 分の試合が約 16 分）。速度は ×1・×2・×4・×8。「最後まで」で結果へ。
 * 実況と点は、ボールがリングに届くころに出す（先に結果が見えないように）。
 * control（クラブ経営）: 自分のチームに、タイムアウト・交代・作戦を指示できる（次のデッドボールで）。
 */
import { useEffect, useMemo, useRef, useState } from 'react'
import { RULES, type RuleSet } from '../../engine'
import { MatchEngine } from '../../engine/match/engine'
import { Choreographer } from '../../engine/match/choreo'
import { comment, type CommentLine } from '../../engine/match/commentary'
import type { Beat, BoxLine, GameEvent, MatchSetup, MatchSummary, Moment, MomentOption, PossLog, SimTeam, Trace } from '../../engine/match/types'
import { CourtRenderer, colorsClash, lerpBeat } from './court'
import { sound } from '../audio/sound'
import { useMusic } from '../audio/useMusic'
import { useSettings } from '../../stores/settingsStore'
import { Icon } from '../components/Icon'
import { SideSheet } from '../layout/SideSheet'
import { ConfirmDialog } from '../components/ConfirmDialog'
import { buzz } from '../audio/haptics'
import { useStageRem } from '../stage/useStage'
import { FlowChart } from './FlowGraph'
import { readableOn } from '../color'

/** 観戦中の選手の成績（実況に出た出来事から数える。エンジンの成績はボールがリングに届く前に進んでいるので使わない） */
interface Tally {
  pts: number
  reb: number
  ast: number
  pf: number
}

/** ×1 での再生の倍率（試合の秒 / 実際の秒） */
const VIEW_RATE = 3

interface Playing {
  log: PossLog
  beats: Beat[]
  /** 実況の出来事と、出す時刻 */
  timed: { t: number; e: GameEvent }[]
  end: number
  /** どこまで出したか */
  shown: number
  cueIdx: number
  /** ポゼッションのはじめの点 */
  base: [number, number]
}

function periodName(rules: RuleSet, p: number): string {
  if (p > rules.periods) return `延長${p - rules.periods > 1 ? p - rules.periods : ''}`
  return rules.periods === 2 ? (p === 1 ? '前半' : '後半') : `第${p}クォーター`
}

function fmtClock(sec: number): string {
  const s = Math.max(0, sec)
  if (s < 60) return s.toFixed(1)
  return `${Math.floor(s / 60)}:${String(Math.floor(s % 60)).padStart(2, '0')}`
}

/** 出来事と、流れ（Trace）の時刻を種類の順に結ぶ */
function timeEvents(events: GameEvent[], marks: { t: number; a: Trace['a'] }[]): { t: number; e: GameEvent }[] {
  const kindOf: Partial<Record<GameEvent['k'], Trace['a']>> = { shot: 'shot', ft: 'ft', reb: 'reb', tov: 'tov', foul: 'foul' }
  const used = new Set<number>()
  return events.map((e) => {
    const a = kindOf[e.k]
    if (!a) return { t: 0, e }
    const i = marks.findIndex((m, j) => m.a === a && !used.has(j))
    if (i < 0) return { t: 0, e }
    used.add(i)
    return { t: marks[i].t, e }
  })
}

export interface MomentResult {
  tried: number
  won: number
}

export function MatchView({ setup, onFinish, focusPlayerId, control }: { setup: MatchSetup; onFinish: (s: MatchSummary, engine: MatchEngine, moments: MomentResult) => void; focusPlayerId?: number; control?: 0 | 1 }) {
  const rules = RULES[setup.rules]
  const engine = useMemo(() => new MatchEngine(setup, { live: true }), [setup])
  const looks = useMemo(() => {
    const m = new Map<number, { pos: SimTeam['players'][number]['pos']; jersey: number; name: string; side: 0 | 1 }>()
    engine.teams.forEach((t, side) => t.players.forEach((p) => m.set(p.id, { pos: p.pos, jersey: p.jersey, name: p.short, side: side as 0 | 1 })))
    return m
  }, [engine])
  const choreo = useMemo(() => new Choreographer((id) => looks.get(id)!, rules, rules.periods), [looks, rules])
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const wrapRef = useRef<HTMLDivElement>(null)
  const startSpeed = useSettings((s) => s.matchSpeed)
  const [speed, setSpeed] = useState<number>(startSpeed)
  const [paused, setPaused] = useState(false)
  const [boxOpen, setBoxOpen] = useState(false)
  const [coachOpen, setCoachOpen] = useState(false)
  /** 「最後まで」の確認 */
  const [skipAsk, setSkipAsk] = useState(false)
  /** 指示を出したら画面を描き直す */
  const [, setTick] = useState(0)
  const [hud, setHud] = useState({ score: [0, 0] as [number, number], period: 1, clock: rules.periodMin * 60, shot: rules.shotClock as number, lines: [] as CommentLine[], on: [] as number[] })
  const [done, setDone] = useState(false)
  /** 試合が終わった（結果の画面。「次へ」で onFinish） */
  const [final, setFinal] = useState<MatchSummary | null>(null)
  const tallyRef = useRef(new Map<number, Tally>())
  /** 実況の記録（新しい順に出す） */
  const logRef = useRef<(CommentLine & { period: number; clock: number; score: [number, number] })[]>([])
  const [boxTab, setBoxTab] = useState<'box' | 'log'>('box')
  const wide = useStageRem() >= 56
  /** 見せ場（選ぶまで止める） */
  const [moment, setMoment] = useState<Moment | null>(null)
  const choiceRef = useRef<MomentOption['id'] | null>(null)
  const momentsRef = useRef<MomentResult>({ tried: 0, won: 0 })
  const [lastMoment, setLastMoment] = useState<{ success: boolean; label: string } | null>(null)
  /** コートの上の短い知らせ（ピリオドの終わり・タイムアウト） */
  const [banner, setBanner] = useState<{ key: number; text: string; sub: string } | null>(null)
  useEffect(() => {
    if (!banner) return
    const id = setTimeout(() => setBanner(null), 2200)
    return () => clearTimeout(id)
  }, [banner])
  const speedRef = useRef(speed)
  const pausedRef = useRef(paused)
  useEffect(() => {
    speedRef.current = speed
  }, [speed])
  useEffect(() => {
    pausedRef.current = paused || boxOpen || coachOpen || !!moment || skipAsk
  }, [paused, boxOpen, coachOpen, moment, skipAsk])
  useMusic('match')

  const home = engine.teams[0]
  const away = engine.teams[1]
  const awayColor = colorsClash(home.colors.primary, away.colors.primary) ? { primary: away.colors.secondary, secondary: away.colors.primary } : away.colors

  useEffect(() => {
    const canvas = canvasRef.current!
    const wrap = wrapRef.current!
    const renderer = new CourtRenderer(canvas, rules, { ...home.colors, numbers: [] }, { ...awayColor, numbers: [] })
    let w = 0
    let h = 0
    const fit = () => {
      w = wrap.clientWidth
      h = wrap.clientHeight
      renderer.resize(canvas, w, h, Math.min(2, window.devicePixelRatio || 1))
    }
    fit()
    const ro = new ResizeObserver(fit)
    ro.observe(wrap)

    const nameOf = (id: number) => looks.get(id)?.name ?? '?'
    const teamName = (s: 0 | 1) => engine.teams[s].short
    let cur: Playing | null = null
    let play = 0
    let last = performance.now()
    let raf = 0
    let finished = false
    const score: [number, number] = [0, 0]
    let lines: CommentLine[] = []
    let lastDribble = 0
    let lastPeriod = 1
    let hudClock = -1

    const next = (): boolean => {
      // 見せ場: 選択を待つ（選んだら次のフレームで進む）
      const m = focusPlayerId !== undefined ? engine.peekMoment() : null
      if (m && !choiceRef.current) {
        if (!pausedRef.current) setMoment(m)
        return true
      }
      const choice = choiceRef.current ?? undefined
      choiceRef.current = null
      const log = engine.step(choice)
      if (!log) return false
      if (log.moment) {
        momentsRef.current.tried++
        if (log.moment.success) momentsRef.current.won++
        const label = m?.options.find((o) => o.id === log.moment!.choice)?.label ?? ''
        setTimeout(() => {
          setLastMoment({ success: log.moment!.success, label })
          if (log.moment!.success) buzz('tap')
        }, 1200)
      }
      if (log.period !== lastPeriod) {
        choreo.resetPositions()
        lastPeriod = log.period
      }
      const { beats, marks } = choreo.build(log)
      const timed = timeEvents(log.events, marks)
      cur = { log, beats, timed, end: (beats[beats.length - 1]?.t ?? log.dur) + 0.25, shown: 0, cueIdx: 0, base: [...score] as [number, number] }
      play = 0
      return true
    }

    const frame = (now: number) => {
      raf = requestAnimationFrame(frame)
      const dt = Math.min(0.1, (now - last) / 1000)
      last = now
      if (!pausedRef.current && !finished) play += dt * VIEW_RATE * speedRef.current
      if (!cur || play >= cur.end) {
        if (!finished && !pausedRef.current) {
          const before = cur
          if (!next()) {
            finished = true
            sound.play('buzzer')
            setDone(true)
            showFinal()
          } else if (cur === before) return
        }
      }
      if (!cur) return
      const c: Playing = cur
      // 実況と点（時刻が来たものから）
      let changed = false
      while (c.shown < c.timed.length && c.timed[c.shown].t <= play) {
        const { e } = c.timed[c.shown++]
        if (e.k === 'shot' && e.made) score[e.side] += e.pts
        if (e.k === 'ft' && e.made) score[e.side] += 1
        tallyEvent(tallyRef.current, e)
        if (e.k === 'shot' && e.made && (e.pts === 3 || e.dunk)) sound.play('cheer')
        if (e.k === 'end') {
          sound.play('buzzer')
          // ピリオドの終わり: コートの上に点を出す（試合の終わりは結果の画面）
          if (e.period < rules.periods || score[0] === score[1]) setBanner({ key: Date.now(), text: `${periodName(rules, e.period)}終了`, sub: `${home.short} ${score[0]} - ${score[1]} ${away.short}` })
        }
        if (e.k === 'timeout') setBanner({ key: Date.now(), text: 'タイムアウト', sub: engine.teams[e.side].short })
        const line = comment(e, nameOf, teamName, (p) => periodName(rules, p))
        if (line) {
          lines = [...lines.slice(-5), line]
          // 実況の記録（成績の小窓の「実況」タブ）
          logRef.current.push({ ...line, period: c.log.period, clock: Math.max(0, c.log.clock - Math.min(play, c.log.dur)), score: [...score] as [number, number] })
        }
        changed = true
      }
      // 効果音
      while (c.cueIdx < c.beats.length && c.beats[c.cueIdx].t <= play) {
        const cue = c.beats[c.cueIdx++].cue
        if (cue === 'dribble' && now - lastDribble > 260) {
          sound.play('dribble')
          lastDribble = now
        } else if (cue === 'swish') sound.play('swish')
        else if (cue === 'rim') sound.play('rim')
        else if (cue === 'dunk') sound.play('dunk')
        else if (cue === 'whistle') sound.play('whistle')
        else if (cue === 'steal') sound.play('squeak')
      }
      // 位置
      const bs = c.beats
      let i = 0
      while (i < bs.length - 1 && bs[i + 1].t <= play) i++
      const a = bs[i]
      const b = bs[Math.min(bs.length - 1, i + 1)]
      const st = lerpBeat(a, b, play)
      const numbers = c.log.lineup.map((id) => looks.get(id)?.jersey ?? 0)
      const focus = focusPlayerId !== undefined ? c.log.lineup.indexOf(focusPlayerId) : -1
      renderer.draw({ pos: st.pos, ball: st.ball, holder: st.holder, focus, numbers }, w, h)
      // 時計（ピリオドの残り・ショットクロック）
      const clock = c.log.clock - Math.min(play, c.log.dur)
      const reb = c.timed.find((x) => x.e.k === 'reb' && x.e.off && x.t <= play)
      const shot = reb ? Math.max(0, 14 - (play - reb.t)) : Math.max(0, rules.shotClock - play)
      if (changed || Math.floor(clock * 10) !== Math.floor(hudClock * 10)) {
        hudClock = clock
        setHud({ score: [...score] as [number, number], period: c.log.period, clock, shot, lines, on: c.log.lineup })
      }
    }
    raf = requestAnimationFrame(frame)
    return () => {
      cancelAnimationFrame(raf)
      ro.disconnect()
    }
    // エンジンは setup ごとに 1 つ（作り直さない）
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [engine])

  /** 試合終了: 結果の画面を出す（上の点と時計も最後に合わせる） */
  function showFinal() {
    const sum = engine.summary()
    setHud((h) => ({ ...h, score: [...sum.score] as [number, number], clock: 0, shot: 0 }))
    setFinal(sum)
  }
  /** 最後まで（結果だけ） */
  const skip = () => {
    // 残りの見せ場は、いちばん見込みの高い手で自動に
    for (;;) {
      const m = focusPlayerId !== undefined ? engine.peekMoment() : null
      const best = m ? [...m.options].sort((a, b) => b.pct - a.pct)[0].id : undefined
      const log = engine.step(best)
      if (!log) break
      if (log.moment) {
        momentsRef.current.tried++
        if (log.moment.success) momentsRef.current.won++
      }
    }
    setMoment(null)
    if (!done) {
      setDone(true)
      showFinal()
    }
  }
  /** 「最後まで」: 試合が進んでいれば確かめる（押し間違えで残りが飛ばないように）。はじまってすぐはそのまま */
  const askSkip = () => {
    if (hud.period === 1 && hud.score[0] + hud.score[1] < 10) skip()
    else setSkipAsk(true)
  }
  /** 結果の画面の「次へ」 */
  const finish = () => {
    if (final) onFinish(final, engine, momentsRef.current)
  }
  // 見ている側（主人公のチーム・指示を出すチーム）
  const mySide: 0 | 1 | undefined = focusPlayerId !== undefined ? (engine.teams[1].players.some((x) => x.id === focusPlayerId) ? 1 : 0) : control
  const choose = (id: MomentOption['id']) => {
    choiceRef.current = id
    setMoment(null)
  }

  // コートをタップで一時停止・再開
  const tapCourt = () => setPaused((p) => !p)

  return (
    <div className="absolute inset-0 flex flex-col bg-[#e9edf2]">
      {/* 上: 点と時計 */}
      <div className="safe-px safe-t flex h-[3.2rem] shrink-0 items-center gap-3" style={{ boxSizing: 'content-box' }}>
        <div className="flex min-w-0 flex-1 items-center justify-end gap-2">
          <span className="truncate text-[0.9rem] font-bold">{home.name}</span>
          <span className="h-6 w-1.5 rounded ring-1 ring-black/15" style={{ background: home.colors.primary }} />
          <span className="num w-[3.2rem] text-right text-[1.6rem] font-black">
            <span key={hud.score[0]} className={hud.score[0] ? 'score-pop' : ''}>
              {hud.score[0]}
            </span>
          </span>
        </div>
        <div className="num flex w-[8.5rem] shrink-0 flex-col items-center leading-tight">
          <span className="text-[0.7rem] font-bold text-ink-dim">{final ? '試合終了' : periodName(rules, hud.period)}</span>
          {final ? (
            <span className="text-[1.1rem] font-black text-ink-dim">FINAL{final.ot ? ` / OT${final.ot > 1 ? final.ot : ''}` : ''}</span>
          ) : (
            <span className="flex items-baseline gap-2">
              <span className="text-[1.2rem] font-black text-gold">{fmtClock(hud.clock)}</span>
              <span className={`rounded bg-[#1b2536] px-1 text-[0.8rem] font-black ${hud.shot <= 5 ? 'text-[#ff6b6b]' : 'text-[#ffc46b]'}`} title="ショットクロック">
                {Math.ceil(hud.shot)}
              </span>
            </span>
          )}
        </div>
        <div className="flex min-w-0 flex-1 items-center gap-2">
          <span className="num w-[3.2rem] text-[1.6rem] font-black">
            <span key={hud.score[1]} className={hud.score[1] ? 'score-pop' : ''}>
              {hud.score[1]}
            </span>
          </span>
          <span className="h-6 w-1.5 rounded ring-1 ring-black/15" style={{ background: awayColor.primary }} />
          <span className="truncate text-[0.9rem] font-bold">{away.name}</span>
        </div>
      </div>
      {/* コート（左右にコートにいる 5 人。幅が足りなければ出さない） */}
      <div className="relative flex min-h-0 flex-1">
        {wide && <OnCourt team={home} color={home.colors.primary} on={hud.on} tally={tallyRef.current} focus={focusPlayerId} />}
        <div ref={wrapRef} className="relative min-w-0 flex-1" onPointerUp={tapCourt}>
          <canvas ref={canvasRef} className="absolute inset-0 h-full w-full" />
          {paused && !done && !moment && <div className="pointer-events-none absolute inset-0 flex items-center justify-center text-[1.4rem] font-black text-[#1b2536]/75">一時停止中（タップで再開）</div>}
          {banner && !final && (
            <div key={banner.key} className="anim-rise pointer-events-none absolute left-1/2 top-1/2 -translate-x-1/2 -translate-y-1/2 rounded-2xl bg-[#1b2536]/85 px-6 py-2.5 text-center text-white shadow-2xl">
              <div className="text-[1.15rem] font-black tracking-wide">{banner.text}</div>
              <div className="num text-[0.9rem] font-bold text-[#ffc46b]">{banner.sub}</div>
            </div>
          )}
          {lastMoment && (
            <div className="anim-rise pointer-events-none absolute left-1/2 top-3 -translate-x-1/2 rounded-full px-4 py-1.5 text-[0.95rem] font-black shadow-xl" style={{ background: lastMoment.success ? 'linear-gradient(90deg,#f5c542,#ff7a1a)' : 'rgba(30,40,70,0.9)', color: lastMoment.success ? '#2a1a00' : '#cbd5e1' }} onAnimationEnd={() => setTimeout(() => setLastMoment(null), 1600)}>
              {lastMoment.success ? `成功！ ${lastMoment.label}` : `失敗… ${lastMoment.label}`}
            </div>
          )}
          {moment && (
            <div className="anim-fade absolute inset-0 flex items-end justify-center bg-black/45 pb-3" onPointerUp={(e) => e.stopPropagation()}>
              <div className="panel panel-solid panel-hero w-[36rem] max-w-[95%] p-3">
                <div className="mb-1 flex items-center gap-2">
                  <span className={`rounded px-2 py-0.5 text-[0.75rem] font-black ${moment.clutch ? 'animate-pulse bg-bad text-white' : 'bg-gold text-[#2a1a00]'}`}>{moment.clutch ? '勝負どころ！' : '見せ場'}</span>
                  <span className="text-[0.85rem] font-bold">ボールが回ってきた。どうする？</span>
                  {/* いまの点と残り時間（勝負どころの判断に） */}
                  <span className="num ml-auto text-[0.75rem] font-bold text-ink-dim">
                    {periodName(rules, hud.period)} 残り {fmtClock(hud.clock)}・{hud.score[0]}-{hud.score[1]}
                  </span>
                </div>
                <div className="grid grid-cols-3 gap-2">
                  {moment.options.map((o) => (
                    <button key={o.id} className="btn btn-ghost !h-auto flex-col !items-start !gap-0.5 !py-2 text-left" onClick={() => choose(o.id)}>
                      <span className="flex w-full items-center gap-2">
                        <span className={`text-[1.3rem] font-black ${o.mark === '◎' ? 'text-gold' : o.mark === '○' ? 'text-orange' : 'text-ink-dim'}`}>{o.mark}</span>
                        <span className="text-[0.92rem] font-black">{o.label}</span>
                      </span>
                      <span className="whitespace-normal text-[0.7rem] font-normal text-ink-dim">
                        <b className="num mr-1 text-ink">見込み {Math.round(o.pct * 100)}%</b>
                        {o.note}
                      </span>
                    </button>
                  ))}
                </div>
                <div className="mt-1 text-[0.68rem] text-ink-mute">◎ 決まりやすい ○ ふつう △ 難しい（% は決まる見込み。能力と、マークする相手で変わる）</div>
              </div>
            </div>
          )}
        </div>
        {wide && <OnCourt team={away} color={awayColor.primary} on={hud.on} tally={tallyRef.current} focus={focusPlayerId} right />}
      </div>
      {/* 下: 実況と操作 */}
      <div className="safe-px safe-b flex h-[4.4rem] shrink-0 items-center gap-2" style={{ boxSizing: 'content-box' }}>
        <div className="min-w-0 flex-1 overflow-hidden text-[0.84rem] leading-snug">
          {hud.lines.slice(-2).map((l, i, arr) => (
            <div key={`${i}:${l.text}`} className={`truncate ${i === arr.length - 1 ? 'text-ink' : 'text-ink-mute'} ${l.big && i === arr.length - 1 ? 'font-black text-gold' : ''}`}>
              {l.text}
            </div>
          ))}
        </div>
        <div className="seg shrink-0">
          {[1, 2, 4, 8].map((v) => (
            <button
              key={v}
              aria-selected={speed === v}
              data-hotkey={`key-${[1, 2, 4, 8].indexOf(v) + 1}`}
              onClick={() => {
                setSpeed(v)
                // 次の試合もこの速さで（設定の「試合の再生速度」）
                useSettings.getState().set({ matchSpeed: v as 1 | 2 | 4 | 8 })
              }}
            >
              ×{v}
            </button>
          ))}
        </div>
        <button className="btn btn-ghost btn-sm" onClick={() => setPaused((p) => !p)} aria-label={paused ? '再開' : '一時停止'} data-hotkey={done ? undefined : 'primary'}>
          <Icon name={paused ? 'play' : 'grid'} className="h-4 w-4" />
          {paused ? '再開' : '停止'}
        </button>
        {control !== undefined && (
          <button className="btn btn-blue btn-sm" onClick={() => setCoachOpen(true)} disabled={done}>
            指示
            {(engine.requests(control).timeout || engine.requests(control).subs.length > 0) && <span className="rounded-full bg-gold px-1.5 text-[0.65rem] font-black text-[#2a1a00]">待</span>}
          </button>
        )}
        <button className="btn btn-ghost btn-sm" onClick={() => setBoxOpen(true)}>
          成績
        </button>
        <button className="btn btn-gold btn-sm" onClick={askSkip} disabled={done}>
          <Icon name="forward" className="h-4 w-4" />
          最後まで
        </button>
      </div>
      {/* 試合終了の結果（画面全体に重ねる。ボタンはいつも見える） */}
      {final && (
        <FinalPanel
          engine={engine}
          summary={final}
          mySide={mySide}
          focusPlayerId={focusPlayerId}
          moments={momentsRef.current}
          rules={rules}
          awayColor={awayColor.primary}
          onBox={() => setBoxOpen(true)}
          onNext={finish}
          plays={logRef.current.filter((l) => l.big && l.side !== undefined && (mySide === undefined || l.side === mySide)).slice(-3).reverse()}
        />
      )}
      <ConfirmDialog
        open={skipAsk}
        title="最後まで進めますか？"
        text={focusPlayerId !== undefined ? '残りは結果だけになります（見せ場は、いちばん決まりやすい手で自動に）。' : '残りは結果だけになります。'}
        ok="最後まで"
        cancel="観戦をつづける"
        onOk={() => {
          setSkipAsk(false)
          skip()
        }}
        onCancel={() => setSkipAsk(false)}
      />
      <SideSheet open={boxOpen} onClose={() => setBoxOpen(false)} title="成績と実況" width="72%">
        <div className="seg mx-3 mb-2">
          <button aria-selected={boxTab === 'box'} onClick={() => setBoxTab('box')}>
            ボックススコア
          </button>
          <button aria-selected={boxTab === 'log'} onClick={() => setBoxTab('log')}>
            実況の記録
          </button>
        </div>
        {boxTab === 'box' ? (
          <BoxScore engine={engine} focus={focusPlayerId} score={final ? undefined : hud.score} />
        ) : (
          <div className="px-3 pb-3 text-[0.78rem]">
            {logRef.current.length === 0 && <div className="text-ink-dim">まだありません。</div>}
            {[...logRef.current].reverse().map((l, i) => (
              <div key={i} className={`flex gap-2 border-t border-line/30 py-0.5 ${l.big ? 'font-bold' : 'text-ink-dim'}`}>
                <span className="num w-[5.2rem] shrink-0 text-ink-mute">
                  {periodName(rules, l.period).replace('クォーター', 'Q')} {fmtClock(l.clock)}
                </span>
                <span className="min-w-0 flex-1">{l.text}</span>
                <span className="num shrink-0 text-ink-mute">
                  {l.score[0]}-{l.score[1]}
                </span>
              </div>
            ))}
          </div>
        )}
      </SideSheet>
      {control !== undefined && (
        <SideSheet open={coachOpen} onClose={() => setCoachOpen(false)} title="監督の指示" width="78%">
          <CoachPanel engine={engine} side={control} onChange={() => setTick((t) => t + 1)} />
        </SideSheet>
      )}
    </div>
  )
}

function tallyEvent(m: Map<number, Tally>, e: GameEvent) {
  const get = (id: number) => {
    let t = m.get(id)
    if (!t) m.set(id, (t = { pts: 0, reb: 0, ast: 0, pf: 0 }))
    return t
  }
  if (e.k === 'shot' && e.made) {
    get(e.pid).pts += e.pts
    if (e.ast !== undefined) get(e.ast).ast++
  } else if (e.k === 'ft' && e.made) get(e.pid).pts++
  else if (e.k === 'reb') get(e.pid).reb++
  else if (e.k === 'foul') get(e.pid).pf++
}

/** コートの横: いまコートにいる 5 人（背番号・名前・得点・ファウル 3 つから）。主人公は金色 */
function OnCourt({ team, color, on, tally, focus, right }: { team: SimTeam; color: string; on: number[]; tally: Map<number, Tally>; focus?: number; right?: boolean }) {
  const five = on.map((id) => team.players.find((p) => p.id === id)).filter((p): p is SimTeam['players'][number] => !!p)
  const bg = readableOn(color, 3.2)
  return (
    <div className={`flex w-[9.2rem] shrink-0 flex-col justify-center gap-1 ${right ? 'pr-2' : 'pl-2'}`}>
      <div className="flex items-center gap-1 px-1 text-[0.68rem] font-black text-ink-dim">
        <span className="h-2.5 w-2.5 shrink-0 rounded-full ring-1 ring-black/15" style={{ background: color }} />
        <span className="min-w-0 flex-1 truncate">{team.short}</span>
        <span className="font-normal">点</span>
      </div>
      {five.map((p) => {
        const t = tally.get(p.id)
        const me = p.id === focus
        const pf = t?.pf ?? 0
        return (
          <div key={p.id} className={`flex items-center gap-1.5 rounded-lg px-1.5 py-1 shadow-sm ${me ? 'bg-[#fff6d8] ring-2 ring-gold' : 'bg-white'}`}>
            <span className="num flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-[0.64rem] font-black text-white" style={{ background: bg }}>
              {p.jersey}
            </span>
            <span className="min-w-0 flex-1 truncate text-[0.74rem] font-bold">{p.short}</span>
            {pf >= 3 && <span className="num text-[0.64rem] font-black text-bad">F{pf}</span>}
            <span className="num w-5 text-right text-[0.84rem] font-black">{t?.pts ?? 0}</span>
          </div>
        )
      })}
    </div>
  )
}

/** ゲームスコア（試合の MVP を決める） */
function gameScore(b: BoxLine): number {
  return b.pts + 0.4 * b.fgm - 0.7 * b.fga - 0.4 * (b.fta - b.ftm) + 0.7 * b.oreb + 0.3 * b.dreb + b.stl + 0.7 * b.ast + 0.7 * b.blk - 0.4 * b.pf - b.tov
}
const statLine = (b: BoxLine) => `${b.pts} 点・${b.oreb + b.dreb} リバウンド・${b.ast} アシスト`

/** 試合終了: 勝ち負け・点・流れ・試合の MVP・自分の成績。「次へ」で週のまとめへ */
function FinalPanel({ engine, summary, mySide, focusPlayerId, moments, rules, awayColor, onBox, onNext, plays }: { engine: MatchEngine; summary: MatchSummary; mySide?: 0 | 1; focusPlayerId?: number; moments: MomentResult; rules: RuleSet; awayColor: string; onBox: () => void; onNext: () => void; plays: (CommentLine & { period: number; clock: number })[] }) {
  const [h, a] = summary.score
  const won = mySide === undefined ? null : mySide === 0 ? h > a : a > h
  const rows = engine.teams.flatMap((t, side) => t.players.map((p) => ({ p, side: side as 0 | 1, b: summary.box[p.id] }))).filter((x) => x.b && x.b.secs > 0)
  rows.sort((x, y) => gameScore(y.b) - gameScore(x.b))
  const mvp = rows[0]
  const me = focusPlayerId !== undefined ? rows.find((x) => x.p.id === focusPlayerId) : undefined
  const best = !me && mySide !== undefined && mvp && mvp.side !== mySide ? rows.find((x) => x.side === mySide) : undefined
  useEffect(() => {
    if (won) {
      sound.play('cheer')
      buzz('win')
    }
  }, [won])
  const colors = [engine.teams[0].colors.primary, awayColor]
  const side = mySide ?? 0
  return (
    <div className="anim-fade absolute inset-0 z-30 flex items-center justify-center bg-black/45 p-3" onPointerUp={(e) => e.stopPropagation()}>
      <div className="panel panel-solid panel-hero relative flex max-h-full w-[34rem] max-w-full flex-col p-4">
        <div className="scroll-y min-h-0">
          <div className="text-center text-[0.75rem] font-bold text-ink-dim">試合終了{summary.ot ? `（延長 ${summary.ot} 回）` : ''}</div>
          <div className="mt-0.5 flex items-center justify-center gap-3">
            <span className={`min-w-0 flex-1 truncate text-right text-[0.95rem] font-black ${h > a ? '' : 'text-ink-dim'}`}>{engine.teams[0].name}</span>
            <span className="num shrink-0 text-[2rem] font-black leading-none">
              {h}
              <span className="mx-1.5 text-ink-mute">-</span>
              {a}
            </span>
            <span className={`min-w-0 flex-1 truncate text-[0.95rem] font-black ${a > h ? '' : 'text-ink-dim'}`}>{engine.teams[1].name}</span>
          </div>
          {won !== null && (
            <div className={`anim-stamp pointer-events-none absolute left-[88%] top-[1.6rem] whitespace-nowrap rounded-lg border-[3px] px-2.5 py-0.5 text-[1.2rem] font-black ${won ? 'border-good text-good' : 'border-bad text-bad'}`} style={{ background: 'rgba(255,255,255,0.85)' }}>
              {won ? '勝利' : '敗戦'}
            </div>
          )}
          {/* ピリオドごとの点 */}
          {(summary.periods?.length ?? 0) > 0 && (
            <table className="num mx-auto mt-1 text-center text-[0.74rem]">
              <thead className="text-[0.64rem] text-ink-mute">
                <tr>
                  <th />
                  {summary.periods!.map((_, i) => (
                    <th key={i} className="w-8 font-normal">
                      {i < rules.periods ? (rules.periods === 2 ? (i === 0 ? '前半' : '後半') : `${i + 1}Q`) : `OT${i - rules.periods + 1 > 1 ? i - rules.periods + 1 : ''}`}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {[0, 1].map((t) => (
                  <tr key={t}>
                    <td className="pr-2 text-left font-bold">{engine.teams[t].short}</td>
                    {summary.periods!.map((p, i) => (
                      <td key={i} className={p[t] > p[1 - t] ? 'font-black' : 'text-ink-dim'}>
                        {p[t]}
                      </td>
                    ))}
                  </tr>
                ))}
              </tbody>
            </table>
          )}
          <FlowChart flow={summary.flow} mine={side} rules={rules} myColor={colors[side]} oppColor={colors[1 - side]} label={`試合の流れ（上が${engine.teams[side].short}のリード）`} className="h-[2.8rem]" />
          <div className="mt-2 space-y-1">
            {mvp && (
              <div className="flex items-center gap-2 rounded-lg bg-gold/15 px-2 py-1">
                <span className="shrink-0 rounded bg-gold px-1.5 py-0.5 text-[0.66rem] font-black text-[#2a1a00]">試合の MVP</span>
                <span className="min-w-0 flex-1 truncate text-[0.84rem] font-black">
                  {mvp.p.short}
                  <span className="ml-1 text-[0.68rem] font-normal text-ink-dim">{engine.teams[mvp.side].short}</span>
                </span>
                <span className="num shrink-0 text-[0.78rem] font-bold">{statLine(mvp.b)}</span>
              </div>
            )}
            {me && (
              <div className={`flex items-center gap-2 rounded-lg px-2 py-1 ${me === mvp ? 'bg-gold/10' : 'bg-black/[0.04]'}`}>
                <span className="shrink-0 rounded bg-[#1b2536] px-1.5 py-0.5 text-[0.66rem] font-black text-white">あなた</span>
                <span className="min-w-0 flex-1 truncate text-[0.84rem] font-black">{me.p.short}</span>
                <span className="num shrink-0 text-[0.78rem] font-bold">
                  {statLine(me.b)}
                  <span className="ml-1 font-normal text-ink-dim">（{Math.round(me.b.secs / 60)} 分）</span>
                </span>
              </div>
            )}
            {focusPlayerId !== undefined && !me && <div className="rounded-lg bg-black/[0.04] px-2 py-1 text-[0.78rem] text-ink-dim">この試合は出番がなかった</div>}
            {best && (
              <div className="flex items-center gap-2 rounded-lg bg-black/[0.04] px-2 py-1">
                <span className="shrink-0 rounded bg-[#1b2536] px-1.5 py-0.5 text-[0.66rem] font-black text-white">チームの 1 位</span>
                <span className="min-w-0 flex-1 truncate text-[0.84rem] font-black">{best.p.short}</span>
                <span className="num shrink-0 text-[0.78rem] font-bold">{statLine(best.b)}</span>
              </div>
            )}
            {moments.tried > 0 && (
              <div className="px-1 text-[0.74rem] text-ink-dim">
                見せ場 <b className="num text-ink">{moments.won}</b> / {moments.tried} 成功
              </div>
            )}
            {plays.length > 0 && (
              // 名場面: 観戦したところの大きなプレー（見ている側の 3P・ダンク・ブロック・スティールなど）を新しい順に 3 つ
              <div className="px-1 text-[0.72rem]">
                <span className="font-black text-ink-dim">名場面</span>
                {plays.map((l, i) => (
                  <div key={i} className="truncate">
                    <span className="num mr-1 text-ink-mute">{periodName(rules, l.period).replace('クォーター', 'Q')} {fmtClock(l.clock)}</span>
                    {l.text}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
        <div className="mt-3 flex shrink-0 gap-2">
          <button className="btn btn-ghost" onClick={onBox}>
            ボックススコア
          </button>
          <button className="btn btn-gold ml-auto min-w-[9rem]" onClick={onNext} data-hotkey="primary">
            次へ
            <Icon name="forward" className="h-4 w-4" />
          </button>
        </div>
      </div>
    </div>
  )
}

/** ボックススコア（両チーム） */
/** score: 観戦中は画面の点（エンジンはボールがリングに届く前に先へ進んでいるので、先に結果が見えないように） */
export function BoxScore({ engine, focus, score }: { engine: MatchEngine; focus?: number; score?: [number, number] }) {
  return (
    <div className="space-y-3 p-2">
      {engine.teams.map((t, side) => (
        <div key={side}>
          <div className="mb-1 flex items-center gap-2 px-1 text-[0.85rem] font-black">
            <span className="h-4 w-1.5 rounded" style={{ background: t.colors.primary }} />
            {t.name}
            <span className="num ml-auto text-[1rem]">{score ? score[side] : t.score}</span>
          </div>
          <table className="num w-full text-center text-[0.75rem]">
            <thead className="text-[0.66rem] text-ink-dim">
              <tr>
                <th className="text-left">選手</th>
                <th>分</th>
                <th>得点</th>
                <th>REB</th>
                <th>AST</th>
                <th>STL</th>
                <th>BLK</th>
                <th>FG</th>
                <th>3P</th>
                <th>FT</th>
                <th>TO</th>
                <th>PF</th>
                <th>+/-</th>
              </tr>
            </thead>
            <tbody>
              {t.players
                .filter((p) => p.box.secs > 0)
                .sort((a, b) => Number(b.box.started) - Number(a.box.started) || b.box.secs - a.box.secs)
                .map((p) => (
                  <tr key={p.id} className={`border-t border-line/30 ${p.id === focus ? 'bg-gold/15 font-bold' : ''}`}>
                    <td className="max-w-[8rem] truncate py-0.5 text-left">
                      <span className="text-ink-mute">{p.jersey} </span>
                      {p.short}
                      {p.box.started && <span className="ml-0.5 text-[0.64rem] text-gold">先</span>}
                    </td>
                    <td>{Math.round(p.box.secs / 60)}</td>
                    <td className="font-black">{p.box.pts}</td>
                    <td>{p.box.oreb + p.box.dreb}</td>
                    <td>{p.box.ast}</td>
                    <td>{p.box.stl}</td>
                    <td>{p.box.blk}</td>
                    <td>
                      {p.box.fgm}-{p.box.fga}
                    </td>
                    <td>
                      {p.box.tpm}-{p.box.tpa}
                    </td>
                    <td>
                      {p.box.ftm}-{p.box.fta}
                    </td>
                    <td>{p.box.tov}</td>
                    <td className={p.box.pf >= 5 ? 'text-bad' : ''}>{p.box.pf}</td>
                    <td className={p.box.pm > 0 ? 'text-good' : p.box.pm < 0 ? 'text-bad' : ''}>{p.box.pm > 0 ? `+${p.box.pm}` : p.box.pm}</td>
                  </tr>
                ))}
            </tbody>
          </table>
        </div>
      ))}
    </div>
  )
}

const TACTIC_OPTS = {
  pace: [
    ['slow', 'ゆっくり'],
    ['normal', 'ふつう'],
    ['fast', '速く'],
  ],
  focus: [
    ['inside', 'インサイド'],
    ['balanced', 'バランス'],
    ['outside', '3P'],
  ],
  defense: [
    ['man', 'マンツー'],
    ['zone23', '2-3 ゾーン'],
    ['zone32', '3-2 ゾーン'],
    ['press', 'プレス'],
  ],
} as const

/** 監督の指示（クラブ経営の観戦）: タイムアウト・交代（出す選手 → 入れる選手）・作戦・交代のおまかせ */
function CoachPanel({ engine, side, onChange }: { engine: MatchEngine; side: 0 | 1; onChange: () => void }) {
  const t = engine.teams[side]
  const req = engine.requests(side)
  const [outId, setOutId] = useState<number | null>(null)
  const foulOut = RULES[engine.setup.rules].foulOut
  const court = t.court.map((i) => t.players[i])
  const bench = t.players.filter((_, i) => !t.court.includes(i))
  const pendingOut = new Set(req.subs.map((s) => s.out))
  const pendingIn = new Set(req.subs.map((s) => s.in))
  const row = (p: SimTeam['players'][number], onCourt: boolean) => {
    const sel = outId === p.id
    const disabled = !onCourt && (outId === null || p.out || p.fouls >= foulOut || pendingIn.has(p.id))
    return (
      <button
        key={p.id}
        disabled={disabled}
        onClick={() => {
          if (onCourt) setOutId(sel ? null : p.id)
          else if (outId !== null && engine.requestSub(side, outId, p.id)) {
            setOutId(null)
            onChange()
          }
        }}
        className={`flex w-full items-center gap-2 rounded-lg border px-2 py-1 text-left text-[0.8rem] ${sel ? 'border-gold bg-gold/15' : 'border-line/40 bg-black/[0.04]'} ${disabled ? 'opacity-45' : 'hover:bg-black/5'}`}
      >
        <span className="num w-6 text-center font-black text-ink-dim">{p.jersey}</span>
        <span className="w-7 text-[0.68rem] font-bold text-orange">{p.pos}</span>
        <span className="min-w-0 flex-1 truncate font-bold">
          {p.short}
          {p.foreignSlot && <span className="ml-1 text-[0.62rem] text-ink-mute">外</span>}
        </span>
        <span className="h-1.5 w-12 overflow-hidden rounded-full bg-black/50">
          <span className="block h-full rounded-full" style={{ width: `${p.energy}%`, background: p.energy > 70 ? '#3ddc84' : p.energy > 50 ? '#ffb020' : '#ff5a5f' }} />
        </span>
        <span className={`num w-10 text-right text-[0.7rem] ${p.fouls >= foulOut - 1 ? 'font-black text-bad' : 'text-ink-dim'}`}>F{p.fouls}</span>
        <span className="num w-9 text-right text-[0.72rem]">{p.box.pts}点</span>
        {(pendingOut.has(p.id) || pendingIn.has(p.id)) && <span className="rounded bg-gold px-1 text-[0.6rem] font-black text-[#2a1a00]">{pendingOut.has(p.id) ? '下がる' : '入る'}</span>}
      </button>
    )
  }
  return (
    <div className="flex h-full gap-3 p-3">
      <div className="scroll-y min-w-0 flex-1 space-y-1">
        <div className="panel-head">コート（下げる選手を選ぶ）</div>
        {court.map((p) => row(p, true))}
        <div className="panel-head pt-1">ベンチ（入れる選手を選ぶ）</div>
        {bench.map((p) => row(p, false))}
      </div>
      <div className="flex w-[15rem] shrink-0 flex-col gap-2">
        <button
          className="btn btn-gold"
          disabled={t.timeouts <= 0 || req.timeout}
          onClick={() => {
            engine.callTimeout(side)
            onChange()
          }}
        >
          {req.timeout ? 'タイムアウトを待っています' : `タイムアウト（残り ${t.timeouts}）`}
        </button>
        <div className="text-[0.68rem] leading-snug text-ink-mute">タイムアウトと交代は、次にボールが止まったときに行います。タイムアウトは相手の流れを止め、コートの 5 人の体力が少し戻ります。</div>
        {(Object.keys(TACTIC_OPTS) as (keyof typeof TACTIC_OPTS)[]).map((k) => (
          <div key={k}>
            <div className="text-[0.72rem] font-bold text-ink-dim">{k === 'pace' ? 'ペース' : k === 'focus' ? '攻めの重心' : '守り'}</div>
            <div className="seg mt-0.5 flex">
              {TACTIC_OPTS[k].map(([v, label]) => (
                <button
                  key={v}
                  className="flex-1 !px-1 text-[0.72rem]"
                  aria-selected={t.tactics[k] === v}
                  onClick={() => {
                    engine.setTactics(side, { [k]: v })
                    onChange()
                  }}
                >
                  {label}
                </button>
              ))}
            </div>
          </div>
        ))}
        <label className="mt-1 flex items-center gap-2 text-[0.78rem]">
          <input
            type="checkbox"
            checked={!t.manual}
            onChange={(e) => {
              engine.setAutoSubs(side, e.target.checked)
              onChange()
            }}
          />
          交代はコーチにおまかせ
        </label>
        <div className="text-[0.66rem] text-ink-mute">おまかせを外すと、自分で交代します（退場とケガだけは自動）。</div>
      </div>
    </div>
  )
}
