/** 資金の推移（最近 52 週。帳簿の週ごとの収支から、いまの資金をさかのぼる） */
function MoneyTrend() {
  const state = useGameState()
  const c = state.club!
  const recent = c.ledger.slice(-52)
  if (recent.length < 3) return null
  // いまの資金から、新しい週の収支を順に引いてさかのぼる（帳簿の合計と資金の動きは同じ。テストあり）
  const pts: number[] = [c.money]
  for (let i = recent.length - 1; i > 0; i--) pts.unshift(pts[0] - ledgerNet(recent[i]))
  const W = 200
  const H = 50
  const lo = Math.min(0, ...pts)
  const hi = Math.max(...pts, lo + 1)
  const x = (i: number) => (i / (pts.length - 1)) * W
  const y = (v: number) => H - 3 - ((v - lo) / (hi - lo)) * (H - 6)
  const line = pts.map((v, i) => `${x(i).toFixed(1)},${y(v).toFixed(1)}`).join(' ')
  const first = pts[0]
  const d = c.money - first
  return (
    <div className="mt-3">
      <div className="flex items-baseline justify-between text-[0.72rem]">
        <span className="font-black text-ink-dim">資金の推移（最近 {pts.length} 週）</span>
        <span className={`num font-bold ${d >= 0 ? 'text-good' : 'text-bad'}`}>
          {d >= 0 ? '+' : ''}
          {yen(d)}
        </span>
      </div>
      <svg viewBox={`0 0 ${W} ${H}`} preserveAspectRatio="none" className="h-[4rem] w-full rounded-md bg-black/[0.035]">
        {lo < 0 && <line x1="0" x2={W} y1={y(0)} y2={y(0)} stroke="#d64545" strokeOpacity="0.5" strokeWidth="0.6" strokeDasharray="2 2" />}
        <polyline points={`0,${H} ${line} ${W},${H}`} fill="#f5c542" fillOpacity="0.25" stroke="none" />
        <polyline points={line} fill="none" stroke="#c98a00" strokeWidth="1.2" vectorEffect="non-scaling-stroke" />
      </svg>
      <div className="num flex justify-between text-[0.64rem] text-ink-mute">
        <span>{yen(first)}</span>
        <span>いま {yen(c.money)}</span>
      </div>
    </div>
  )
}

