/**
 * クラブ経営の「街と事業」（2026-11-15）: クラブの事業（club/business.ts）と、ホームタウンの街づくり（club/town.ts。街のマップ）。
 * ナビの列はいっぱいなので、クラブのホーム・メニュー・クラブの画面から開く。
 */
import { useCurrentScreen } from '../../stores/uiStore'
import { useGame, useGameState } from '../../stores/gameStore'
import { AppShell } from '../layout/AppShell'
import { useScreenState } from '../hooks/useScreenState'
import { useConfirm } from '../hooks/useConfirm'
import { Term } from '../components/Term'
import { formatMoneyShort } from '../format'
import { CLUB_BIZ, CLUB_BIZ_MAX, bizCost, bizSellValue, bizWeekly, bizYearly, clubBiz, clubEconomy, economyLabel, growBiz, sellBiz } from '../../engine/club/business'
import { clubTeam } from '../../engine/club/manage'
import { DISTRICT_NAME, PERK_LABEL, TOWN_MAX_LV, TOWN_PROJECTS, TOWN_PROJECT_BY_ID, TOWN_STAT_NAME, nextLv, projectCost, projectDelta, projectLv, projectPerks, projectProblem, projectWeeks, startProject, townBase, townBonus, townOf, townRank, townStats, townUpkeep, type TownStat } from '../../engine/club/town'
import { townImageUrl } from '../components/portraits'
import { HOMETOWN_BY_ID } from '../../engine/data/club'
import { TownMap } from '../club/TownMap'
import { useState } from 'react'
import { absWeekOf } from '../../engine'

type Tab = 'town' | 'biz'
const yen = (man: number) => `${formatMoneyShort(Math.round(man))}円`
const sign = (man: number) => `${man >= 0 ? '+' : ''}${yen(man)}`

function BizTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const confirm = useConfirm()
  const c = state.club!
  const econ = clubEconomy(state)
  const total = (c.biz ?? []).reduce((s, b) => s + b.total, 0)
  return (
    <div className="space-y-2">
      {confirm.dialog}
      <div className="flex flex-wrap items-center gap-x-4 gap-y-0.5 text-[0.78rem]">
        <span>
          景気: <b className={econ >= 1 ? 'text-good' : 'text-bad'}>{economyLabel(econ)}</b>
        </span>
        <span>
          1 年の損益の見込み: <b className={bizYearly(state) >= 0 ? 'text-good' : 'text-bad'}>{sign(bizYearly(state))}</b>
        </span>
        <span>
          通算: <b className="num">{sign(total)}</b>
        </span>
      </div>
      <p className="text-[0.72rem] leading-snug text-ink-dim">
        <Term id="clubBiz">クラブの事業</Term>は、儲けは控えめで、クラブへの効き目が主です。費用はいまの部の大きさで決まり（上の部ほど高い）、売るときは注ぎ込んだお金の 6 割が戻ります。毎週の損益は人気と景気（8 週ごとに動く）で変わります。
      </p>
      <div className="grid grid-cols-3 gap-2">
        {CLUB_BIZ.map((d) => {
          const b = clubBiz(state, d.id)
          const lv = b?.level ?? 0
          const cost = bizCost(state, d.id)
          return (
            <div key={d.id} className={`panel-flat flex flex-col gap-1 p-2.5 ${b ? 'border-gold bg-gold/10' : ''}`}>
              <div className="flex items-center gap-1">
                <span className="text-[0.92rem] font-black">{d.name}</span>
                {b && <span className="ml-auto rounded bg-gold px-1.5 text-[0.66rem] font-black text-[#2a1a00]">Lv{lv}</span>}
              </div>
              <div className="text-[0.68rem] leading-snug text-ink-dim">{d.desc}</div>
              <div className="text-[0.72rem]">
                効き目: <b className="text-good">{lv > 0 ? d.effect(lv) : 'なし'}</b>
                {lv < CLUB_BIZ_MAX && <span className="ml-1 text-ink-dim">→ Lv{lv + 1}: {d.effect(lv + 1)}</span>}
              </div>
              {b && (
                <div className="num text-[0.7rem] text-ink-dim">
                  週 <b className={bizWeekly(state, b) >= 0 ? 'text-good' : 'text-bad'}>{sign(bizWeekly(state, b))}</b>・今季 {sign(b.season)}・注ぎ込んだお金 {yen(b.invested)}
                </div>
              )}
              <div className="mt-auto flex gap-1">
                {cost !== null ? (
                  <button
                    className={`btn btn-sm flex-1 !px-1 ${b ? 'btn-ghost' : 'btn-gold'}`}
                    disabled={c.money < cost}
                    onClick={() =>
                      confirm.ask({ title: b ? `${d.name}を Lv${lv + 1} に広げますか？` : `${d.name}を始めますか？`, text: `${yen(cost)} を資金から払います。`, ok: b ? '広げる' : '始める' }, () => mutate((st) => void growBiz(st, d.id)))
                    }
                  >
                    <span className="text-[0.76rem]">{b ? `広げる ${yen(cost)}` : `始める ${yen(cost)}`}</span>
                  </button>
                ) : (
                  <span className="flex-1 self-center text-center text-[0.74rem] text-gold">いちばん大きい</span>
                )}
                {b && (
                  <button
                    className="btn btn-ghost btn-sm !px-2"
                    onClick={() => confirm.ask({ title: `${d.name}を売りますか？`, text: `注ぎ込んだお金の 6 割（${yen(bizSellValue(b))}）を受け取ります。効き目はなくなります。`, ok: '売る' }, () => mutate((st) => void sellBiz(st, d.id)))}
                  >
                    <span className="text-[0.76rem]">売る</span>
                  </button>
                )}
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

/** 計画の段の画像（なければ SVG の代わりの札） */
function ProjectImage({ id, lv, faded, className = '' }: { id: string; lv: number; faded?: boolean; className?: string }) {
  const url = townImageUrl(id, lv)
  return (
    <div className={`relative overflow-hidden rounded-lg bg-[#f4efe3] ${className}`} style={{ aspectRatio: '3 / 2', opacity: faded ? 0.38 : 1 }}>
      {url ? (
        <img src={url} alt="" className="absolute inset-0 h-full w-full object-cover" loading="lazy" draggable={false} />
      ) : (
        <div className="absolute inset-0 grid place-items-center text-[0.66rem] font-bold text-ink-mute">Lv{lv}</div>
      )}
    </div>
  )
}

const perkText = (id: string, lv: number) => projectPerks(id, lv).map((x) => PERK_LABEL[x.kind](x.v))
const deltaText = (g: Partial<Record<TownStat, number>>) => (Object.keys(g) as TownStat[]).map((k) => `${TOWN_STAT_NAME[k]} +${g[k]}`)

/** 街のマップと、右の欄（街のランク・指標・効き目・選んだ計画） */
function TownTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const confirm = useConfirm()
  const c = state.club!
  const team = clubTeam(state)
  const [sel, setSel] = useState<string | undefined>(undefined)
  const t = townOf(state)
  const s = townStats(state)
  const base = townBase(state)
  const b = townBonus(state)
  const rank = townRank(state)
  const nba = team.league === 'NBA'
  const gameDay = state.fixtures.some((f) => f.week === state.week && f.home === c.teamId)
  const p = sel ? TOWN_PROJECT_BY_ID[sel] : undefined
  const why = p ? projectProblem(state, p.id) : null
  const lv = p ? projectLv(state, p.id) : 0
  const to = p ? nextLv(state, p.id) : undefined
  const buildingThis = !!p && t.building?.id === p.id
  const pct = (v: number) => `+${Math.round((v - 1) * 100)}%`
  const effects = [
    b.attendance > 1.005 && `観客 ${pct(b.attendance)}`,
    b.sponsor > 1.005 && `スポンサー ${pct(b.sponsor)}`,
    !nba && b.fanCeiling > 0 && `ファンの天井 +${b.fanCeiling.toLocaleString()} 人`,
    b.fanGrowth > 1.005 && `ファンの増え方 ${pct(b.fanGrowth)}`,
    b.popularity > 0.05 && `人気 +${b.popularity.toFixed(1)}`,
    b.youthPot > 0.05 && `U18 の素質 +${b.youthPot.toFixed(1)}`,
    b.ticket > 1.005 && `入場料 ${pct(b.ticket)}`,
    b.goods > 1.005 && `グッズ ${pct(b.goods)}`,
    b.chemistry > 0 && `まとまり +${b.chemistry.toFixed(0)}`,
  ].filter(Boolean) as string[]
  const builtCount = Object.keys(t.built).length
  const lv3Count = Object.keys(t.built).filter((id) => projectLv(state, id) >= 3).length
  return (
    <div className="flex h-full gap-2">
      {confirm.dialog}
      <div className="relative min-w-0 flex-1 overflow-hidden rounded-xl border border-line/50 bg-[#e4ecd2]">
        <TownMap state={state} selected={sel} onSelect={setSel} color={team.colors.primary} abbr={team.abbr} gameDay={gameDay} />
        {gameDay && <div className="pointer-events-none absolute right-2 top-2 rounded-full bg-orange px-2 py-0.5 text-[0.66rem] font-black text-white">今週はホームの試合</div>}
      </div>
      <div className="scroll-y flex w-[16.5rem] shrink-0 flex-col gap-2 text-[0.76rem]">
        <div className="panel-flat p-2">
          <div className="flex items-baseline gap-1.5">
            <span className="text-[0.95rem] font-black">{HOMETOWN_BY_ID[c.hometown].city}</span>
            <span className="rounded bg-gold/20 px-1.5 text-[0.74rem] font-black text-gold">{rank.name}</span>
          </div>
          <div className="mt-0.5 flex items-center gap-1.5 text-[0.68rem] text-ink-dim">
            <span className="shrink-0">街のランク {rank.level}/5</span>
            <span className="relative h-1.5 flex-1 overflow-hidden rounded-full bg-black/10">
              <span className="absolute inset-y-0 left-0 rounded-full bg-gold" style={{ width: `${rank.progress * 100}%` }} />
            </span>
            {rank.next && <span className="shrink-0">→ {rank.next}</span>}
          </div>
          {(Object.keys(TOWN_STAT_NAME) as TownStat[]).map((k) => (
            <div key={k} className="mt-0.5 flex items-center gap-1.5">
              <span className="w-[5.2rem] shrink-0">{TOWN_STAT_NAME[k]}</span>
              <span className="relative h-2 flex-1 overflow-hidden rounded-full bg-black/10">
                <span className="absolute inset-y-0 left-0 rounded-full bg-[#9aa6b6]" style={{ width: `${base[k]}%` }} />
                <span className="absolute inset-y-0 rounded-full bg-good" style={{ left: `${base[k]}%`, width: `${s[k] - base[k]}%` }} />
              </span>
              <b className="num w-6 text-right">{s[k]}</b>
            </div>
          ))}
          <div className="mt-1 text-[0.7rem] leading-snug text-ink-dim">
            {effects.length ? `効き目: ${effects.join('・')}` : '計画を建てると、指標が上がって効き目が出ます（緑のぶん）。指標が上がるほど、マップの街も育ちます。'}
          </div>
          <div className="num mt-0.5 text-[0.68rem] text-ink-mute">
            計画 {builtCount}/{TOWN_PROJECTS.length}（Lv3 {lv3Count}）{townUpkeep(state) > 0 && `・維持費 年 ${yen(townUpkeep(state))}`}
          </div>
          {t.building && <div className="mt-0.5 font-bold text-orange">建てている: {TOWN_PROJECT_BY_ID[t.building.id]?.name}{(t.building.lv ?? 1) > 1 ? `（Lv${t.building.lv}）` : ''}</div>}
        </div>
        {p ? (
          <div className="panel-flat flex flex-col gap-1 p-2">
            <div className="flex items-center gap-1 text-[0.7rem] text-ink-dim">
              <span>{DISTRICT_NAME[p.district]}</span>
              {p.minLeague && <span className="rounded bg-black/[0.06] px-1">{p.minLeague === 'JBL2' ? '2 部から' : p.minLeague === 'JBL1' ? '1 部から' : 'NBA'}</span>}
              <span className="ml-auto font-black text-gold">{lv > 0 ? '★'.repeat(lv) + '☆'.repeat(TOWN_MAX_LV - lv) : 'まだ'}</span>
            </div>
            <div className="text-[0.95rem] font-black leading-tight">{p.name}</div>
            {/* いまの段の画像（建てていなければ Lv1 の完成予想） */}
            <div className="relative">
              <ProjectImage id={p.id} lv={Math.max(1, buildingThis ? (t.building!.lv ?? 1) : lv)} />
              <span className="absolute left-1 top-1 rounded bg-white/90 px-1 text-[0.64rem] font-black text-ink">
                {buildingThis ? `工事中 → Lv${t.building!.lv ?? 1}` : lv > 0 ? `Lv${lv}` : '完成予想'}
              </span>
            </div>
            <div className="grid grid-cols-3 gap-1">
              {[1, 2, 3].map((l) => (
                <div key={l} className="relative">
                  <ProjectImage id={p.id} lv={l} faded={l > lv} />
                  <span className={`absolute bottom-0.5 left-0.5 rounded px-0.5 text-[0.6rem] font-black ${l <= lv ? 'bg-gold text-[#2a1a00]' : 'bg-white/90 text-ink-dim'}`}>Lv{l}</span>
                </div>
              ))}
            </div>
            <div className="text-[0.72rem] text-ink-dim">{p.desc}</div>
            {lv > 0 && (
              <div className="text-[0.72rem]">
                いま: <b className="text-good">{[...deltaText(projectDelta(state, p.id, 0)), ...perkText(p.id, lv)].join('・') || '—'}</b>
              </div>
            )}
            {buildingThis ? (
              <div className="font-black text-orange">建てている（あと {Math.max(0, t.building!.doneAbs - absWeekOf(state.season, state.week))} 週）</div>
            ) : to ? (
              <>
                <div className="text-[0.72rem]">
                  {lv > 0 ? `Lv${to} にすると` : 'できあがると'}: <b className="text-good">{[...deltaText(projectDelta(state, p.id, to)), ...perkText(p.id, to)].join('・') || '指標はほぼいっぱい'}</b>
                </div>
                <div className="num text-[0.72rem]">
                  費用 <b>{yen(projectCost(state, p.id))}</b>・{projectWeeks(state, p.id)} 週・維持費 年 +{yen(projectCost(state, p.id) * 0.04)}
                </div>
                {why && <div className="text-[0.72rem] font-bold text-bad">{why}</div>}
                <button
                  className="btn btn-gold btn-sm mt-0.5"
                  disabled={!!why}
                  data-hotkey="primary"
                  onClick={() =>
                    confirm.ask(
                      {
                        title: lv > 0 ? `「${p.name}」を Lv${to} に広げますか？` : `「${p.name}」を建てますか？`,
                        text: `費用 ${yen(projectCost(state, p.id))} をその場で払います。${projectWeeks(state, p.id)} 週でできあがり、毎年の維持費が ${yen(projectCost(state, p.id) * 0.04)} 増えます。`,
                        ok: lv > 0 ? '広げる' : '建てる',
                      },
                      () => mutate((st) => void startProject(st, p.id)),
                    )
                  }
                >
                  <span className="text-[0.8rem]">{lv > 0 ? `Lv${to} に広げる` : '建てる'}</span>
                </button>
              </>
            ) : (
              <div className="font-black text-gold">いちばん大きい（Lv{TOWN_MAX_LV}）</div>
            )}
          </div>
        ) : (
          <div className="panel-flat p-2 text-[0.74rem] text-ink-dim">
            マップの <b className="text-gold">＋</b> を押すと、そこに建てる計画が出ます。建てた計画も押すと、Lv2・Lv3 に広げられます（Lv3 は 1 部から）。薄い ＋ は今は建てられない区画です（先に建てる計画がある・上の部に上がってから・ほかを建てている・資金が足りない）。計画は 1 つずつ建てます。下の部のうちに建てるほど安く済みます。
            {nba && <div className="mt-1">NBA ではファンは日本中から集まるので、ファンの天井には効きません（観客・スポンサーなどには効く）。</div>}
          </div>
        )}
      </div>
    </div>
  )
}

export function TownScreen() {
  const state = useGameState()
  const screen = useCurrentScreen()
  const c = state.club!
  const team = clubTeam(state)
  const [tab, setTab] = useScreenState<Tab>('tab', 'town', screen.params?.tab as Tab | undefined)
  return (
    <AppShell title="街と事業" current="club" tipId="town" back color={team.colors.primary} right={<span className={`num text-[0.85rem] font-bold ${c.money < 0 ? 'text-bad' : 'text-gold'}`}>資金 {yen(c.money)}</span>}>
      <div className="absolute inset-0 flex flex-col gap-2 p-2">
        <div className="seg shrink-0 self-start">
          <button aria-selected={tab === 'town'} onClick={() => setTab('town')}>
            街づくり
          </button>
          <button aria-selected={tab === 'biz'} onClick={() => setTab('biz')}>
            クラブの事業
          </button>
        </div>
        {tab === 'town' ? (
          <div className="min-h-0 flex-1">
            <TownTab />
          </div>
        ) : (
          <div className="panel scroll-y min-h-0 flex-1 p-3">
            <BizTab />
          </div>
        )}
      </div>
    </AppShell>
  )
}
